// =====================================================
// NORMALIZE PATIENT SPECIES
// =====================================================

function normalizeVaccineSpecies(
  value
) {
  const raw =
    String(value || "")
      .trim()
      .toLowerCase();

  if (
    [
      "dog",
      "собака",
      "пес",
    ].includes(raw)
  ) {
    return "dog";
  }

  if (
    [
      "cat",
      "кіт",
      "кішка",
      "кот",
      "кошка",
    ].includes(raw)
  ) {
    return "cat";
  }

  return "other";
}


// =====================================================
// GET VACCINE BRANDS FOR PATIENT
// =====================================================

function getVaccineBrandsForPatient(
  pet
) {
  const species =
    normalizeVaccineSpecies(
      pet?.species
    );

  return VACCINE_CATALOG.filter(
    (brand) =>
      brand.species.includes(
        species
      )
  );
}
// =====================================================
// VACCINE COVERAGE TAGS
// =====================================================

function getVaccineCoverageTags(
  brand,
  vaccine
) {
  const brandName =
    String(
      brand?.brand || ""
    ).trim();

  const vaccineName =
    String(
      vaccine?.name || ""
    ).trim();

  const category =
    String(
      vaccine?.category || ""
    ).trim();

  const key =
    `${brandName}|${vaccineName}`;


  // Специальные комбинированные
  // препараты, которые закрывают
  // сразу несколько направлений.

  const overrides = {
    "Nobivac|DHPPi+RL": [
  "general",
  "lepto",
  "rabies",
],

"Biocan|DHPPi+L(R)": [
  "general",
  "lepto",
  "rabies",
],

"Eurican|DHPPi2-LR": [
  "general",
  "lepto",
  "rabies",
],

"Canigen|DHA2PPi/LR": [
  "general",
  "lepto",
  "rabies",
],

"Felocell / Felovax|Rabies combination": [
  "general",
  "rabies",
],
    "Nobivac|RL": [
      "rabies",
      "lepto",
    ],

    "Biocan|Novel DHPPi/L4": [
      "general",
      "lepto",
    ],

    "Biocan|Novel DHPPi/L4R": [
      "general",
      "lepto",
      "rabies",
    ],

    "Vanguard|Plus 5/L": [
      "general",
      "lepto",
    ],

    "Vanguard|Plus 5/CVL": [
      "general",
      "lepto",
    ],

    "Vanguard|DAPP/L4": [
      "general",
      "lepto",
    ],

    "Canigen|DHPPi/L": [
      "general",
      "lepto",
    ],

    "Versican Plus|DHPPi/L4": [
      "general",
      "lepto",
    ],

    "Versican Plus|DHPPi/L4R": [
      "general",
      "lepto",
      "rabies",
    ],

    "Purevax|RCPCh": [
      "general",
    ],

    "Purevax|RCP FeLV": [
      "general",
      "felv",
    ],

    "Biofel|PCHR": [
      "general",
      "rabies",
    ],

    "TruFel|HCP + FeLV": [
      "general",
      "felv",
    ],
  };


  if (overrides[key]) {
    return [
      ...overrides[key]
    ];
  }


  // Обычные категории.

  if (
    category === "viral"
  ) {
    return [
      "general"
    ];
  }

  if (
    category === "rabies"
  ) {
    return [
      "rabies"
    ];
  }

  if (
    category === "lepto"
  ) {
    return [
      "lepto"
    ];
  }

  if (
    category ===
    "respiratory"
  ) {
    return [
      "respiratory"
    ];
  }

  if (
    category === "felv"
  ) {
    return [
      "felv"
    ];
  }


  // Неизвестную вакцину лучше
  // не классифицировать автоматически.

  return [];
}

