function getCurrentVetWaitingEvents(
  events = []
) {
  const currentStaffId =
    getCurrentStaffId();

  if (!currentStaffId) {
    return [];
  }

  return (
    Array.isArray(events)
      ? events
      : []
  ).filter(
    (event) => {
      const eventStaffId =
        String(
          event?.staff_id || ""
        ).trim();

      const eventStatus =
        String(
          event?.status || ""
        )
          .trim()
          .toLowerCase();

      return (
        eventStaffId ===
          currentStaffId &&
        eventStatus ===
          "waiting"
      );
    }
  );
}

