let tasksBadgeLoading =
  false;


async function refreshMyTasksBadge() {
  if (tasksBadgeLoading) {
    return;
  }


  const taskMenuItem =
    document.querySelector(
      '#tabs [data-target="tasks"], ' +
      '#tabs [data-route="tasks"]'
    );


  if (!taskMenuItem) {
    return;
  }


  const taskMenuLink =
    taskMenuItem.querySelector(
      "a"
    ) ||
    taskMenuItem;


  let badge =
    taskMenuItem.querySelector(
      ".taskMenuBadge"
    );


  if (!badge) {
    badge =
      document.createElement(
        "span"
      );

    badge.className =
      "taskMenuBadge";

    badge.style.cssText = `
      display:none;
      align-items:center;
      justify-content:center;
      min-width:20px;
      height:20px;
      padding:0 6px;
      margin-left:6px;
      border-radius:999px;
      background:#ff625c;
      color:#fff;
      font-size:11px;
      font-weight:800;
      line-height:1;
      box-shadow:
        0 4px 14px
        rgba(255,98,92,.35);
    `;

    taskMenuLink.appendChild(
      badge
    );
  }


  tasksBadgeLoading =
    true;


  try {
    const params =
      new URLSearchParams({
        scope:
          "mine",

        status:
          "open",
      });


    const response =
      await fetch(
        `/api/tasks?${params.toString()}`,
        {
          method:
            "GET",

          credentials:
            "include",

          cache:
            "no-store",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );


    const result =
      await response
        .json()
        .catch(
          () => null
        );


    if (
      !response.ok ||
      !result?.ok
    ) {
      throw new Error(
        result?.error ||
        "Не вдалося завантажити задачі."
      );
    }


    const tasks =
      Array.isArray(
        result.data
      )
        ? result.data
        : [];
const currentTaskIds =
  tasks
    .map(
      (task) =>
        String(
          task?.id || ""
        ).trim()
    )
    .filter(
      Boolean
    );


if (!taskNotificationsReady) {
  currentTaskIds.forEach(
    (taskId) => {
      knownMyTaskIds.add(
        taskId
      );
    }
  );

  taskNotificationsReady =
    true;

} else {
  const newTasks =
    tasks.filter(
      (task) => {
        const taskId =
          String(
            task?.id || ""
          ).trim();

        return (
          taskId &&
          !knownMyTaskIds.has(
            taskId
          )
        );
      }
    );


  currentTaskIds.forEach(
    (taskId) => {
      knownMyTaskIds.add(
        taskId
      );
    }
  );


  if (
    newTasks.length
  ) {
    showAssignedTaskToast(
      newTasks[0],
      Math.max(
        0,
        newTasks.length - 1
      )
    );
  }
}

    const openTasks =
      tasks.filter(
        (task) =>
          String(
            task?.status ||
            "open"
          )
            .trim()
            .toLowerCase() !==
          "completed"
      );


    const count =
      openTasks.length;


    if (count > 0) {
      badge.textContent =
        count > 99
          ? "99+"
          : String(count);

      badge.style.display =
        "inline-flex";

    } else {
      badge.textContent =
        "";

      badge.style.display =
        "none";
    }

  } catch (error) {
    console.warn(
      "refreshMyTasksBadge failed:",
      error
    );

  } finally {
    tasksBadgeLoading =
      false;
  }
}


function startTasksBadgePoll() {
  if (tasksBadgePollStarted) {
    return;
  }


  tasksBadgePollStarted =
    true;


  refreshMyTasksBadge();


  setInterval(
    () => {
      refreshMyTasksBadge();
    },
    30000
  );
}

function isOwner() {
  return (
    getCurrentCrmRole() ===
    "owner"
  );
}


function isOwnerOrAdmin() {
  return [
    "owner",
    "admin",
  ].includes(
    getCurrentCrmRole()
  );
}


function canAccessRoute(
  route
) {
  const cleanRoute =
    String(route || "")
      .trim()
      .toLowerCase();

  const role =
    getCurrentCrmRole();

  const allowedRoutes =
    CRM_ROLE_ACCESS[role]
      ?.routes || [];

  return (
    allowedRoutes.includes("*") ||
    allowedRoutes.includes(
      cleanRoute
    )
  );
}


function canManageAllCalendar() {
  return [
    "owner",
    "admin",
    "assistant",
  ].includes(
    getCurrentCrmRole()
  );
}


function canManageCalendarStaff(
  staffId
) {
  if (canManageAllCalendar()) {
    return true;
  }

  const currentStaffId =
    getCurrentStaffId();

  return Boolean(
    currentStaffId &&
    String(staffId || "") ===
      currentStaffId
  );
}


function canOpenStaffProfile(
  staffId
) {
  if (isOwnerOrAdmin()) {
    return true;
  }

  const currentStaffId =
    getCurrentStaffId();

  return Boolean(
    currentStaffId &&
    String(staffId || "") ===
      currentStaffId
  );
}


function getDefaultAllowedRoute() {
  const preferred = [
    "calendar",
    "owners",
    "patients",
    "visits",
  ];

  return (
    preferred.find(
      canAccessRoute
    ) ||
    "owners"
  );
}


