const TAB_ROUTES = new Set([
  "owners",
  "patients",
  "visits",
  "hospital",
  "services",
  "calendar",
  "tasks",
  "stock",
  "finance",
  "team",
  "audit",
  "settings",
]);

function parseHash() {
  const raw = (location.hash || "").replace("#", "").trim();
  if (!raw) return { route: "owners", id: null };

  const [routeRaw, idRaw] = raw.split(":");
  const route = (routeRaw || "owners").trim() || "owners";
  const id = idRaw != null ? String(idRaw).trim() : null;
  return { route, id };
}

function setHash(route, id = null) {
  const r = String(route || "owners").trim() || "owners";
    if (
    TAB_ROUTES.has(r) &&
    !canAccessRoute(r)
  ) {
    const fallback =
      getDefaultAllowedRoute();

    showCrmNotice({
      icon: "🔒",
      title: "Доступ обмежено",
      text:
        "Ваша роль не має доступу до цього розділу.",
    });

    if (
      location.hash.replace(
        "#",
        ""
      ) !== fallback
    ) {
      location.hash =
        fallback;
    }

    return;
  }
  const next = id ? `${r}:${id}` : r;
  if (location.hash.replace("#", "") !== next) location.hash = next;
}

function setRoute(route) {
  const r = String(route || "owners").trim() || "owners";
  const pageExists = document.querySelector(`.page[data-page="${r}"]`);
  const finalRoute = pageExists ? r : "owners";

  state.route = finalRoute;

  document.body.dataset.currentRoute =
  finalRoute;

const ownersSearchInput =
  document.getElementById(
    "globalSearch"
  );

const ownersSearchWrap =
  ownersSearchInput
    ?.parentElement;

if (ownersSearchWrap) {
  ownersSearchWrap.classList.add(
    "ownersGlobalSearchWrap"
  );

  ownersSearchWrap.hidden =
    finalRoute !== "owners";

  ownersSearchWrap.style.display =
    finalRoute === "owners"
      ? ""
      : "none";
}

if (ownersSearchInput) {
  ownersSearchInput.placeholder =
    "Власник, телефон, улюбленець, порода...";

  ownersSearchInput.setAttribute(
    "aria-label",
    "Пошук власників та улюбленців"
  );
}

  // Переключаем секции (в новом HTML они скрыты через display: none)
  Array.from(document.querySelectorAll(".page")).forEach((p) => {
    p.classList.toggle("active", p.dataset.page === finalRoute);
    if (p.dataset.page === finalRoute) {
      p.style.display = "block";
    } else {
      p.style.display = "none";
    }
  });

  // Подсвечиваем активную вкладку в новом боковом меню
  if (TAB_ROUTES.has(finalRoute)) {
    Array.from(document.querySelectorAll("#tabs .menu-item, #tabs .tab")).forEach((btn) => {
      const btnRoute = btn.dataset.target || btn.dataset.route;
      btn.classList.toggle("active", btnRoute === finalRoute);
    });
  }
}

function initTabs() {
  const tabs = document.getElementById("tabs");
  if (!tabs) return;

  tabs.addEventListener("click", (e) => {
    // Ловим клик по новому классу .menu-item
    const btn = e.target.closest(".menu-item") || e.target.closest(".tab");
    if (!btn) return;
    
    // Берем маршрут из нового data-target
    const route = btn.dataset.target || btn.dataset.route;
    if (!TAB_ROUTES.has(route)) return;
    
    setHash(route);
  });

  window.addEventListener("hashchange", routeFromHash);
  routeFromHash();
}

async function routeFromHash() {
  const { route, id } = parseHash();

  startTasksBadgePoll();
  if (
    TAB_ROUTES.has(route) &&
    !canAccessRoute(route)
  ) {
    const fallback =
      getDefaultAllowedRoute();

    showCrmNotice({
      icon: "🔒",
      title: "Доступ обмежено",
      text:
        "Цей розділ недоступний для вашої ролі.",
    });

    setHash(fallback);
    return;
  }
  if (TAB_ROUTES.has(route)) {
    setRoute(route);
    if (
  route === "owners"
) {
  renderOwners();

  await loadOwners();
}
    if (route === "patients") renderPatientsTab();
    if (route === "visits") renderVisitsTab();
if (route === "hospital") renderHospitalTab();
if (route === "services") renderServicesTab();
    if (route === "stock") renderStockTab();
    if (
  route === "finance"
) {
  await renderFinanceTab();
}
    if (route === "team") renderTeamTab();
    if (route === "tasks") {
  await renderTasksTab();
}
    if (route === "audit") {
      await renderAuditTab();
    }
    if (route === "calendar") {
  state.selectedVisitId = null;

  if (
    typeof closeVisitModal ===
    "function"
  ) {
    closeVisitModal();
  }

  await renderCalendarTab();
}
     if (route === "settings") {
       // Поскольку настройки статические, просто инициализируем их UI
       initSettingsUI();
    }
    return;
  }

  if (route === "owner") {
    if (id) openOwner(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "patient") {
    if (id) openPatient(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "visit") {
    if (id) openVisit(id, { pushHash: false });
    else setHash("owners");
    return;
  }

  if (route === "settings") renderSettingsTab();

  setHash("owners");
}

// ===== API /api/me =====
async function loadMe() {
  if (location.protocol === "file:") {
    state.me = null;
    setApiStatus(false, "API: /api/me ❌ (открыто через file://)");
    setMeLine("Гость • открой через http://localhost:8080");
    return;
  }

  setApiStatus(null, "API: проверяю /api/me …");
  setMeLine("Загрузка профиля…");

  try {
    const res = await fetch("/api/me", { credentials: "include" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const data = await res.json();

    state.me = data?.user || data?.me || data || null;
    const name = state.me?.name || state.me?.first_name || state.me?.username || "Пользователь";
    const tgId = state.me?.tg_user_id || state.me?.id || state.me?.user_id || null;

    setApiStatus(true, "API: /api/me ✅");
    setMeLine(tgId ? `${name} • tg_id: ${tgId}` : `${name}`);
  } catch {
    state.me = null;
    setApiStatus(false, "API: /api/me ❌ (пока нет бэка — это ок)");
    setMeLine("Гость • подключим бэк позже");
  }
}

// ===== Storage seed =====
function seedIfEmpty() {
  if (!LS.get(VISITS_KEY, null)) LS.set(VISITS_KEY, []);
  if (!LS.get(FILES_KEY, null)) LS.set(FILES_KEY, []);
  if (!LS.get(VISIT_FILES_KEY, null)) LS.set(VISIT_FILES_KEY, []);
  if (!LS.get(DISCHARGES_KEY, null)) LS.set(DISCHARGES_KEY, {});

  if (!LS.get(STOCK_KEY, null)) {
    LS.set(STOCK_KEY, [
      { id: "stk_meloxivet", name: "Мелоксивет", price: 70, unit: "шт", qty: 10, active: true },
    ]);
  }

  if (
  location.protocol ===
    "file:" &&
  !LS.get(
    SERVICES_KEY,
    null
  )
) {
  LS.set(
    SERVICES_KEY,
    [
      {
        id: "svc_exam",
        name: "Огляд",
        price: 500,
        active: true,
        cat: "Терапія",
      },
      {
        id: "svc_vax",
        name: "Вакцинація",
        price: 800,
        active: true,
        cat: "Терапія",
      },
    ]
  );
}

  if (location.protocol !== "file:") return;

  const owners = LS.get(OWNERS_KEY, []);
  const patients = LS.get(PATIENTS_KEY, []);

  if (!owners.length) {
    const ownerId = String(Date.now());
    LS.set(OWNERS_KEY, [
      { id: ownerId, name: "Іван Петренко", phone: "+38050…", note: "Боярка" },
    ]);

    LS.set(PATIENTS_KEY, [
      {
        id: String(Date.now() + 1),
        owner_id: ownerId,
        name: "Мойша",
        species: "пес",
        breed: "Мопс",
        age: "3.8",
        weight_kg: "5",
        notes: "Чешет нос",
      },
    ]);
  } else {
    if (!Array.isArray(patients)) LS.set(PATIENTS_KEY, []);
  }
}



// ===== API: Owners =====
// ===== API: Owners =====
let ownersApiInFlight =
  null;


async function loadOwners(
  force = false
) {
  if (
    ownersApiInFlight &&
    !force
  ) {
    return ownersApiInFlight;
  }


  const cachedOwners =
    Array.isArray(
      state.owners
    ) &&
    state.owners.length
      ? state.owners
      : (
          Array.isArray(
            LS.get(
              OWNERS_KEY,
              []
            )
          )
            ? LS.get(
                OWNERS_KEY,
                []
              )
            : []
        );


  ownersApiInFlight =
    (async () => {
      const attempts = 3;

      const delays = [
        0,
        350,
        900,
      ];


      for (
        let attempt = 0;
        attempt < attempts;
        attempt++
      ) {
        if (
          delays[attempt]
        ) {
          await new Promise(
            (resolve) =>
              setTimeout(
                resolve,
                delays[attempt]
              )
          );
        }


        try {
          const response =
            await fetch(
              "/api/owners",
              {
                method:
                  "GET",

                credentials:
                  "include",

                cache:
                  "no-store",

                headers: {
                  Accept:
                    "application/json",

                  ...getOrgHeaders(),
                },
              }
            );


          const text =
            await response.text();


          let json = null;

          try {
            json =
              text
                ? JSON.parse(
                    text
                  )
                : null;

          } catch (
            parseError
          ) {
            throw new Error(
              "Сервер повернув некоректну відповідь."
            );
          }


          if (
            !response.ok ||
            !json ||
            json.ok !== true
          ) {
            throw new Error(
              json?.error ||
              `HTTP ${response.status}`
            );
          }


          const owners =
            Array.isArray(
              json.data
            )
              ? json.data
              : json.data
                ? [
                    json.data
                  ]
                : [];


          state.owners =
            owners;


          LS.set(
            OWNERS_KEY,
            owners
          );


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          if (
            state.route ===
              "owner" &&
            state.selectedOwnerId
          ) {
            await renderOwnerPage(
              state.selectedOwnerId
            );
          }


          return owners;

        } catch (error) {
          console.warn(
            `loadOwners attempt ${
              attempt + 1
            }/${attempts} failed:`,
            error
          );


          if (
            attempt <
            attempts - 1
          ) {
            continue;
          }


          console.error(
            "loadOwners failed after retries:",
            error
          );


          /*
           * ВАЖНО:
           * при временной ошибке
           * НЕ очищаем владельцев.
           */

          state.owners =
            cachedOwners;


          if (
            state.route ===
            "owners"
          ) {
            renderOwners();
          }


          return cachedOwners;
        }
      }


      return cachedOwners;
    })();


  try {
    return await ownersApiInFlight;

  } finally {
    ownersApiInFlight =
      null;
  }
}
// ===== API: Patients =====
let patientsApiInFlight = null;
let patientsApiLoading = false;
let patientsApiLoaded = false;

async function loadPatientsApi() {
  if (patientsApiInFlight) {
    return patientsApiInFlight;
  }

  patientsApiLoading = true;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  patientsApiInFlight =
    loadPatientsApiRequest();

  try {
    return await patientsApiInFlight;
  } finally {
  patientsApiLoaded = true;
  patientsApiLoading = false;
  patientsApiInFlight = null;

  if (state.route === "patients") {
    renderPatientsTab();
  }

  if (state.route === "owners") {
    renderOwners();
  }

  if (
    state.route === "owner" &&
    state.selectedOwnerId
  ) {
    await renderOwnerPage(
      state.selectedOwnerId
    );
  }
}
}

async function loadPatientsApiRequest() {
  const cachedPatients =
    Array.isArray(state.patients)
      ? state.patients
      : [];

  try {
    const res = await fetch("/api/patients", {
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    });

    const text = await res.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (!res.ok) {
      console.error(
        "API /patients HTTP",
        res.status,
        text
      );

      alert(
        `Помилка завантаження пацієнтів (HTTP ${res.status})`
      );

      state.patients =
        cachedPatients;

      if (state.route === "patients") {
        renderPatientsTab();
      }

      if (
        state.route === "owner" &&
        state.selectedOwnerId
      ) {
        await renderOwnerPage(
          state.selectedOwnerId
        );
      }

      return cachedPatients;
    }

    if (!json || !json.ok) {
      console.error(
        "API /patients bad json",
        json,
        text
      );

      alert(
        json?.error ||
        "Помилка завантаження пацієнтів"
      );

      state.patients =
        cachedPatients;

      if (state.route === "patients") {
        renderPatientsTab();
      }

      if (
        state.route === "owner" &&
        state.selectedOwnerId
      ) {
        await renderOwnerPage(
          state.selectedOwnerId
        );
      }

      return cachedPatients;
    }

    const arr = Array.isArray(json.data)
      ? json.data
      : json.data
        ? [json.data]
        : [];

    state.patients = arr;

    savePatients(arr);

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(
        state.selectedOwnerId
      );
    }

    return arr;
  } catch (e) {
    console.error(
      "loadPatientsApi failed:",
      e
    );

    alert(
      "Помилка завантаження пацієнтів (network)"
    );

    state.patients =
      cachedPatients;

    if (state.route === "patients") {
      renderPatientsTab();
    }

    if (
      state.route === "owner" &&
      state.selectedOwnerId
    ) {
      await renderOwnerPage(
        state.selectedOwnerId
      );
    }

    return cachedPatients;
  }
}

