async function loadServicesApi() {
  try {
    const res = await fetch("/api/services", {
      credentials: "include",
      headers: { Accept: "application/json", ...getOrgHeaders() },
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (
  !res.ok ||
  !json ||
  !json.ok
) {
  console.warn(
    "loadServicesApi failed:",
    res.status,
    text
  );

  state.services = [];

  return [];
}

    const arr = Array.isArray(json.data) ? json.data : (json.data ? [json.data] : []);
    const catMap = loadServicesCatMap();

    const merged = (Array.isArray(arr) ? arr : []).map((s) => {
      const id = String(s?.id || "");
      const savedCat = catMap[id];
      const rawCat = (s?.cat ?? s?.category ?? s?.section ?? s?.group ?? s?.type ?? savedCat ?? "");
      const cat = String(rawCat || "").trim() || "Інше";
      return { ...s, cat };
    });

    state.services = merged;
    LS.set(SERVICES_KEY, merged);
    return merged;
  } catch (e) {
  console.warn(
    "loadServicesApi network fail:",
    e
  );

  state.services = [];

  return [];
}
}
async function loadAppointmentTemplatesApi(
  force = false
) {
  if (
    state.appointmentTemplatesLoaded &&
    !force
  ) {
    return state.appointmentTemplates;
  }

  try {
    const response =
      await fetch(
        "/api/appointment-templates",
        {
          credentials: "include",

          headers: {
            Accept:
              "application/json",

            ...getOrgHeaders(),
          },
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json =
        text
          ? JSON.parse(text)
          : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "loadAppointmentTemplatesApi failed:",
        response.status,
        text
      );

      return [];
    }

    const templates =
      Array.isArray(json.data)
        ? json.data
        : [];

    state.appointmentTemplates =
      templates;

    state.appointmentTemplatesLoaded =
      true;

    return templates;

  } catch (error) {
    console.error(
      "loadAppointmentTemplatesApi error:",
      error
    );

    return [];
  }
}

async function createAppointmentTemplateApi(
  payload
) {
  try {
    const response =
      await fetch(
        "/api/appointment-templates",
        {
          method: "POST",

          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify(
              payload || {}
            ),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json =
        text
          ? JSON.parse(text)
          : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "createAppointmentTemplateApi failed:",
        response.status,
        text
      );

      throw new Error(
        json?.error ||
        "Не вдалося створити шаблон."
      );
    }

    return Array.isArray(
      json.data
    )
      ? json.data[0] || null
      : json.data || null;

  } catch (error) {
    console.error(
      "createAppointmentTemplateApi error:",
      error
    );

    throw error;
  }
}
function renderAppointmentTemplatePicker() {
  const list =
    document.getElementById(
      "appointmentTemplateList"
    );

  if (!list) {
    return;
  }

  const templates =
    Array.isArray(
      state.appointmentTemplates
    )
      ? state.appointmentTemplates
          .filter(
            (template) =>
              template.active !== false
          )
      : [];

  if (!templates.length) {
    list.innerHTML = `
      <div class="appointmentTemplateEmpty">
        Шаблонів поки немає
      </div>
    `;

    return;
  }

  const selectedId =
    String(
      document.getElementById(
        "visitTemplateId"
      )?.value || ""
    );

  list.innerHTML =
    templates
      .map((template) => {
        const id =
          String(
            template.id || ""
          );

        const selected =
          id === selectedId;

        return `
          <button
            type="button"
            class="
              appointmentTemplateCard
              ${
                selected
                  ? "active"
                  : ""
              }
            "
            data-appointment-template-id="${escapeHtml(
              id
            )}"
            style="
              --template-color:
              ${escapeHtml(
                template.color ||
                "#7C5CFF"
              )};
            "
          >
            <span class="appointmentTemplateIcon">
              ${escapeHtml(
                template.icon ||
                "📅"
              )}
            </span>

            <span class="appointmentTemplateText">
              <strong>
                ${escapeHtml(
                  template.name ||
                  "Прийом"
                )}
              </strong>

              <small>
                ${Number(
                  template.duration_min ||
                  30
                )} хв
              </small>
            </span>
          </button>
        `;
      })
      .join("");
}
function updateAppointmentTemplateSelector() {
  const templateId =
    String(
      document.getElementById(
        "visitTemplateId"
      )?.value || ""
    ).trim();

  const iconElement =
    document.getElementById(
      "appointmentTemplateSelectorIcon"
    );

  const nameElement =
    document.getElementById(
      "appointmentTemplateSelectorName"
    );

  const metaElement =
    document.getElementById(
      "appointmentTemplateSelectorMeta"
    );

  const selector =
    document.getElementById(
      "appointmentTemplateSelector"
    );

  const template =
    (
      state.appointmentTemplates ||
      []
    ).find(
      (item) =>
        String(item.id) ===
        templateId
    );

  if (!template) {
    if (iconElement) {
      iconElement.textContent =
        "🩺";
    }

    if (nameElement) {
      nameElement.textContent =
        "Обрати шаблон";
    }

    if (metaElement) {
      metaElement.textContent =
        "Тривалість і тип прийому";
    }

    if (selector) {
      selector.style.removeProperty(
        "--template-color"
      );

      selector.classList.remove(
        "has-template"
      );
    }

    return;
  }

  if (iconElement) {
    iconElement.textContent =
      String(
        template.icon ||
        "📅"
      );
  }

  if (nameElement) {
    nameElement.textContent =
      String(
        template.name ||
        "Прийом"
      );
  }

  if (metaElement) {
    metaElement.textContent =
      `${Number(
        template.duration_min ||
        30
      )} хв · шаблон вибрано`;
  }

  if (selector) {
    selector.style.setProperty(
      "--template-color",
      String(
        template.color ||
        "#7C5CFF"
      )
    );

    selector.classList.add(
      "has-template"
    );
  }
}

function bindAppointmentTemplatePicker() {
  const list =
    document.getElementById(
      "appointmentTemplateList"
    );

  if (
    !list ||
    list.dataset.bound === "1"
  ) {
    return;
  }

  list.dataset.bound =
    "1";

  list.addEventListener(
    "click",
    (event) => {
      const button =
        event.target.closest(
          "[data-appointment-template-id]"
        );

      if (!button) {
        return;
      }

      const templateId =
        String(
          button.dataset
            .appointmentTemplateId ||
          ""
        );

      const template =
        state.appointmentTemplates
          .find(
            (item) =>
              String(item.id) ===
              templateId
          );

      if (!template) {
        return;
      }

      const templateInput =
        document.getElementById(
          "visitTemplateId"
        );

      const durationInput =
        document.getElementById(
          "visitDuration"
        );

      const noteInput =
        document.getElementById(
          "visitNote"
        );

      const clearButton =
        document.getElementById(
          "appointmentTemplateClear"
        );

      if (templateInput) {
        templateInput.value =
          templateId;
      }

      if (durationInput) {
        const duration =
          String(
            template.duration_min ||
            30
          );

        let option =
          Array.from(
            durationInput.options
          ).find(
            (item) =>
              item.value ===
              duration
          );

        if (!option) {
          option =
            document.createElement(
              "option"
            );

          option.value =
            duration;

          option.textContent =
            `${duration} хв`;

          durationInput.appendChild(
            option
          );
        }

        durationInput.value =
          duration;
      }

      if (noteInput) {
        const currentNote =
          String(
            noteInput.value || ""
          ).trim();

        const defaultNote =
          String(
            template.default_note ||
            template.name ||
            ""
          ).trim();

        if (
          !currentNote &&
          defaultNote
        ) {
          noteInput.value =
            defaultNote;
        }
      }

      if (clearButton) {
  clearButton.hidden =
    false;
}

renderAppointmentTemplatePicker();

updateAppointmentTemplateSelector();
    }
  );
}
function bindAppointmentTemplateDrawer() {
  const drawer =
    document.getElementById(
      "appointmentTemplateDrawer"
    );

  const selector =
    document.getElementById(
      "appointmentTemplateSelector"
    );

  const quickAdd =
    document.getElementById(
      "appointmentTemplateAddQuick"
    );

  const drawerAdd =
    document.getElementById(
      "appointmentTemplateDrawerAdd"
    );

  const closeButton =
    document.getElementById(
      "appointmentTemplateDrawerClose"
    );

  const backdrop =
    document.getElementById(
      "appointmentTemplateDrawerBackdrop"
    );

  if (!drawer) {
    console.error(
      "appointmentTemplateDrawer not found"
    );

    return;
  }

  const openDrawer = () => {
    drawer.style.display =
      "flex";

    drawer.classList.add(
      "is-open"
    );

    drawer.setAttribute(
      "aria-hidden",
      "false"
    );

    console.log(
      "template drawer opened"
    );
  };

  const closeDrawer = () => {
    drawer.classList.remove(
      "is-open"
    );

    drawer.setAttribute(
      "aria-hidden",
      "true"
    );

    drawer.style.display =
      "none";
  };

  if (selector) {
    selector.onclick =
      openDrawer;
  }

  if (quickAdd) {
    quickAdd.onclick =
      () => {
        openAppointmentTemplateEditor();
      };
  }

  if (drawerAdd) {
    drawerAdd.onclick =
      () => {
        openAppointmentTemplateEditor();
      };
  }

  if (closeButton) {
    closeButton.onclick =
      closeDrawer;
  }

  if (backdrop) {
    backdrop.onclick =
      closeDrawer;
  }

  drawer.onclick =
    (event) => {
      const templateButton =
        event.target.closest(
          "[data-appointment-template-id]"
        );

      if (!templateButton) {
        return;
      }

      setTimeout(
        closeDrawer,
        100
      );
    };
}
