async function loadHospitalizationsApi(
  active = true
) {
  try {
    const url =
      `/api/hospitalizations?active=${
        active ? "true" : "false"
      }`;

    const response = await fetch(url, {
      method: "GET",
      credentials: "include",
      headers: {
        Accept: "application/json",
        ...getOrgHeaders(),
      },
    });

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "loadHospitalizationsApi failed:",
        response.status,
        text
      );

      return [];
    }

    return Array.isArray(json.data)
      ? json.data
      : [];
  } catch (error) {
    console.error(
      "loadHospitalizationsApi error:",
      error
    );

    return [];
  }
}


