async function dischargeHospitalizationApi(
  hospitalizationId,
  notes = ""
) {
  const currentRole =
    String(
      state.me?.role || ""
    ).toLowerCase();

  if (currentRole === "assistant") {
    openDeleteModal(
      `
        Виписувати пацієнтів зі стаціонару
        можуть ветеринар, адміністратор
        або власник клініки.
      `,
      null,
      "info"
    );

    return null;
  }

  try {
    const response =
      await fetch(
        `/api/hospitalizations/${
          encodeURIComponent(
            String(
              hospitalizationId
            )
          )
        }/discharge`,
        {
          method: "POST",
          credentials: "include",

          headers: {
            "Content-Type":
              "application/json",

            Accept:
              "application/json",

            ...getOrgHeaders(),
          },

          body:
            JSON.stringify({
              notes:
                String(
                  notes || ""
                ).trim(),
            }),
        }
      );

    const text =
      await response.text();

    let json = null;

    try {
      json = text
        ? JSON.parse(text)
        : null;
    } catch {}

    if (
      !response.ok ||
      !json ||
      json.ok !== true
    ) {
      console.error(
        "dischargeHospitalizationApi failed:",
        response.status,
        text
      );

      openDeleteModal(
        `
          ${
            json?.error ||
            "Не вдалося виписати пацієнта."
          }
        `,
        null,
        "info"
      );

      return null;
    }

    return json.data || null;

  } catch (error) {
    console.error(
      "dischargeHospitalizationApi error:",
      error
    );

    openDeleteModal(
      `
        Не вдалося з'єднатися із сервером.
      `,
      null,
      "info"
    );

    return null;
  }
}

async function createServiceApi(payload) {
  try {
    const res = await fetch("/api/services", {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json", Accept: "application/json", ...getOrgHeaders() },
      body: JSON.stringify(payload || {}),
    });
    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok || !json || !json.ok) return null;
    return Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
  } catch (e) {
    console.error("createServiceApi failed:", e);
    return null;
  }
}

