async function visitTaskApiRequest(
  url,
  options = {}
) {
  const response =
    await fetch(
      url,
      {
        credentials:
          "include",

        headers: {
          Accept:
            "application/json",

          ...(
            options.body
              ? {
                  "Content-Type":
                    "application/json",
                }
              : {}
          ),

          ...getOrgHeaders(),
          ...(options.headers || {}),
        },

        ...options,
      }
    );

  const text =
    await response.text();

  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {
    json = null;
  }

  if (
    !response.ok ||
    json?.ok !== true
  ) {
    console.error(
      "visitTaskApiRequest failed:",
      response.status,
      text
    );

    throw new Error(
      json?.error ||
      `HTTP ${response.status}`
    );
  }

  return json.data;
}


