function formatVisitTaskDate(
  task
) {
  const dueDate =
    String(
      task?.due_date || ""
    ).slice(0, 10);

  const dueTime =
    String(
      task?.due_time || ""
    ).slice(0, 5);

  if (!dueDate) {
    return "Без дати";
  }

  const dateLabel =
    new Date(
      `${dueDate}T00:00:00`
    ).toLocaleDateString(
      "uk-UA",
      {
        day: "2-digit",
        month: "2-digit",
        year: "numeric",
      }
    );

  return dueTime
    ? `${dateLabel} · ${dueTime}`
    : dateLabel;
}


function getVisitTaskPriorityMeta(
  priority
) {
  const priorities = {
    low: {
      label: "Низький",
      icon: "↓",
    },

    normal: {
      label: "Звичайний",
      icon: "•",
    },

    high: {
      label: "Важливо",
      icon: "!",
    },
  };

  return (
    priorities[priority] ||
    priorities.normal
  );
}


