function ensureVisitStockShape(visit) {
  if (!visit) return;
  if (!Array.isArray(visit.stock)) visit.stock = [];
}

async function addStockLineToVisit(
  visitId,
  stockId,
  qty = 1
) {
  return enqueueVisitMutation(
    visitId,
    () => addStockLineToVisitNow(
      visitId,
      stockId,
      qty
    )
  );
}


async function addStockLineToVisitNow(
  visitId,
  stockId,
  qty = 1
) {
  if (
    !visitId ||
    !stockId
  ) {
    return false;
  }

  const vid =
    String(visitId);

  const current =
    getVisitByIdSync(vid) ||
    await fetchVisitById(vid);

  if (!current) {
    throw new Error(
      "Візит не знайдено."
    );
  }

  ensureVisitStockShape(
    current
  );

  const stockItem =
    getStockById(stockId);

  if (
    !stockItem ||
    stockItem.active === false
  ) {
    throw new Error(
      "Препарат не знайдено або він неактивний."
    );
  }

  const quantity =
    Math.max(
      1,
      Number(qty) || 1
    );

  const data =
    await stockApiRequest(
      `/api/visits/${encodeURIComponent(
        vid
      )}/stock`,
      {
        method: "POST",

        body: JSON.stringify({
          stock_id:
            String(stockId),

          quantity,

          price_snap:
            Number(
              stockItem.price || 0
            ),
        }),
      }
    );

  const line =
    data?.line;

  if (!line?.id) {
    throw new Error(
      "Сервер не повернув рядок препарату."
    );
  }

  current.stock = [
    ...current.stock,
    line,
  ];

  current.stock_json =
    current.stock;

  state.visitsById.set(
    vid,
    current
  );

  if (
    String(
      state.selectedVisitId
    ) === vid
  ) {
    state.selectedVisit =
      current;
  }

  if (data?.stock) {
    const updatedStock =
      normalizeStockItem(
        data.stock
      );

    state.stock =
      loadStock().map(
        (item) =>
          String(item.id) ===
          String(updatedStock.id)
            ? updatedStock
            : item
      );

    state.stockLoaded = true;
  }

  return true;
}

