function getServiceCategories(
  services
) {
  const categories =
    Array.from(
      new Set(
        (services || [])
          .map((service) =>
            String(
              service?.cat ||
              "Інше"
            ).trim()
          )
          .filter(Boolean)
      )
    );

  const preferredOrder = [
    "Терапія",
    "Аналізи",
    "Хірургія",
    "Діагностика",
    "Вакцинація",
    "Стоматологія",
    "Стаціонар",
    "Виїзд",
    "Інше",
  ];

  return categories.sort(
    (a, b) => {
      const indexA =
        preferredOrder.indexOf(a);

      const indexB =
        preferredOrder.indexOf(b);

      return (
        (
          indexA === -1
            ? 999
            : indexA
        ) -
        (
          indexB === -1
            ? 999
            : indexB
        )
      );
    }
  );
}


