function getStockCategories(
  items
) {
  const usedCategories =
    new Set(
      (items || [])
        .map((item) =>
          String(
            item?.category ||
            item?.cat ||
            "Інше"
          ).trim()
        )
        .filter(Boolean)
    );

  const ordered = [];

  STOCK_CATEGORY_GROUPS.forEach(
    (group) => {
      group.categories.forEach(
        (category) => {
          if (
            usedCategories.has(
              category
            )
          ) {
            ordered.push(category);
          }
        }
      );
    }
  );

  usedCategories.forEach(
    (category) => {
      if (
        !ordered.includes(category)
      ) {
        ordered.push(category);
      }
    }
  );

  return ordered;
}


function getStockStatus(item) {
  const quantity = Math.max(
    0,
    Number(item?.qty || 0)
  );

  const minimum = Math.max(
    0,
    Number(
      item?.min_qty ??
      item?.minimum_qty ??
      5
    )
  );

  if (quantity <= 0) {
    return {
      key: "empty",
      label: "Немає в наявності",
      shortLabel: "Немає",
      icon: "○",
    };
  }

  if (quantity <= minimum) {
    return {
      key: "critical",
      label: "Критичний залишок",
      shortLabel: "Критично",
      icon: "!",
    };
  }

  if (quantity <= minimum * 2) {
    return {
      key: "low",
      label: "Закінчується",
      shortLabel: "Мало",
      icon: "↓",
    };
  }

  return {
    key: "good",
    label: "Достатній запас",
    shortLabel: "В наявності",
    icon: "✓",
  };
}


function parseStockDate(value) {
  const match =
    String(value || "")
      .match(
        /^(\d{4})-(\d{2})-(\d{2})$/
      );

  if (!match) return null;

  const parsed =
    new Date(
      Number(match[1]),
      Number(match[2]) - 1,
      Number(match[3])
    );

  return Number.isNaN(
    parsed.getTime()
  )
    ? null
    : parsed;
}


function formatStockDate(value) {
  const parsed =
    parseStockDate(value);

  return parsed
    ? parsed.toLocaleDateString(
        "uk-UA"
      )
    : "";
}


function getStockExpiryMeta(
  item,
  now = new Date()
) {
  const expiryDate =
    parseStockDate(
      item?.expiry_date
    );

  if (!expiryDate) {
    return {
      key: "none",
      days: null,
      label: "",
    };
  }

  const today =
    new Date(
      now.getFullYear(),
      now.getMonth(),
      now.getDate()
    );

  const days =
    Math.ceil(
      (
        expiryDate.getTime()
        - today.getTime()
      )
      / 86400000
    );

  if (days < 0) {
    return {
      key: "expired",
      days,
      label: "Термін минув",
    };
  }

  if (days <= 30) {
    return {
      key: "critical",
      days,
      label:
        days === 0
          ? "Останній день"
          : `${days} дн. до завершення`,
    };
  }

  if (days <= 90) {
    return {
      key: "warning",
      days,
      label:
        `${days} дн. до завершення`,
    };
  }

  return {
    key: "good",
    days,
    label:
      `Придатний до ${formatStockDate(
        item.expiry_date
      )}`,
  };
}


function buildStockPugInsights(items) {
  const signals = [];
  const attentionItemIds =
    new Set();
  let expiryRiskCount = 0;
  let forecastRiskCount = 0;
  let valueAtRisk = 0;

  (items || [])
    .filter(
      (item) =>
        item?.active !== false
    )
    .forEach((item) => {
      const itemId =
        String(item.id || "");
      const quantity =
        Math.max(
          0,
          Number(item.qty || 0)
        );
      const minimum =
        Math.max(
          0,
          Number(item.min_qty || 0)
        );
      const cost =
        Math.max(
          0,
          Number(item.cost || 0)
        );
      const expiry =
        getStockExpiryMeta(item);
      const estimatedDaysLeft =
        item.estimated_days_left ==
        null
          ? null
          : Math.max(
              0,
              Number(
                item.estimated_days_left
              )
            );

      if (
        expiry.key === "expired" ||
        expiry.key === "critical"
      ) {
        expiryRiskCount += 1;
        attentionItemIds.add(itemId);
        valueAtRisk +=
          quantity * cost;

        signals.push({
          priority:
            expiry.key === "expired"
              ? 0
              : 1,
          tone:
            expiry.key === "expired"
              ? "danger"
              : "warning",
          icon:
            expiry.key === "expired"
              ? "!"
              : "◷",
          itemId,
          title:
            expiry.key === "expired"
              ? `${item.name}: термін придатності минув`
              : `${item.name}: ${expiry.label.toLowerCase()}`,
          description:
            quantity > 0
              ? `Під ризиком ${quantity.toLocaleString(
                  "uk-UA"
                )} ${item.unit}.`
              : "Перевірте позицію перед використанням.",
        });
      }

      if (quantity <= 0) {
        attentionItemIds.add(itemId);

        signals.push({
          priority: 0,
          tone: "danger",
          icon: "0",
          itemId,
          title:
            `${item.name} закінчився`,
          description:
            minimum > 0
              ? `Рекомендований мінімум — ${minimum.toLocaleString(
                  "uk-UA"
                )} ${item.unit}.`
              : "Позиція недоступна для використання.",
        });
      } else if (
        quantity <= minimum
      ) {
        attentionItemIds.add(itemId);

        signals.push({
          priority: 1,
          tone: "warning",
          icon: "↓",
          itemId,
          title:
            `${item.name}: критичний залишок`,
          description:
            `Залишилось ${quantity.toLocaleString(
              "uk-UA"
            )} ${item.unit}, мінімум — ${minimum.toLocaleString(
              "uk-UA"
            )}.`,
        });
      }

      if (
        estimatedDaysLeft != null &&
        estimatedDaysLeft > 0 &&
        estimatedDaysLeft <= 14 &&
        quantity > minimum
      ) {
        forecastRiskCount += 1;
        attentionItemIds.add(itemId);

        signals.push({
          priority:
            estimatedDaysLeft <= 7
              ? 1
              : 2,
          tone:
            estimatedDaysLeft <= 7
              ? "warning"
              : "info",
          icon: "↘",
          itemId,
          title:
            `${item.name} вистачить приблизно на ${Math.max(
              1,
              Math.round(
                estimatedDaysLeft
              )
            )} дн.`,
          description:
            "Прогноз за списаннями останніх 30 днів.",
        });
      }
    });

  signals.sort(
    (left, right) =>
      left.priority -
      right.priority
  );

  return {
    signals,
    attentionCount:
      attentionItemIds.size,
    expiryRiskCount,
    forecastRiskCount,
    valueAtRisk,
  };
}


