// =====================================================
// FINANCE PURCHASES: RECEIVE DELIVERY
// =====================================================

async function receiveFinancePurchaseApi(
  purchaseId,
  items,
  note = ""
) {
  const cleanPurchaseId =
    String(
      purchaseId || ""
    ).trim();

  if (!cleanPurchaseId) {
    throw new Error(
      "Не вказано закупівлю."
    );
  }

  if (
    !Array.isArray(items) ||
    !items.length
  ) {
    throw new Error(
      "Додайте хоча б одну позицію приймання."
    );
  }

  const cleanItems =
    items
      .map((item) => {
        const itemId =
          String(
            item?.item_id ||
            item?.purchase_item_id ||
            item?.id ||
            ""
          ).trim();

        const quantity =
          Number(
            item?.quantity ??
            item?.qty ??
            0
          );

        return {
          item_id: itemId,
          quantity,
        };
      })
      .filter(
        (item) =>
          item.item_id &&
          Number.isFinite(
            item.quantity
          ) &&
          item.quantity > 0
      );

  if (!cleanItems.length) {
    throw new Error(
      "Не вказано коректну кількість для приймання."
    );
  }

  const idempotencyKey =
    typeof crypto
      ?.randomUUID ===
      "function"
      ? crypto.randomUUID()
      : [
          "purchase-receipt",
          cleanPurchaseId,
          Date.now(),
          Math.random()
            .toString(16)
            .slice(2),
        ].join("-");

  const response =
    await fetch(
      `/api/finance/purchases/${
        encodeURIComponent(
          cleanPurchaseId
        )
      }/receive`,
      {
        method: "POST",

        credentials: "include",

        headers: {
          "Content-Type":
            "application/json",

          Accept:
            "application/json",

          ...getOrgHeaders(),
        },

        body: JSON.stringify({
          items:
            cleanItems,

          note:
            String(
              note || ""
            ).trim(),

          idempotency_key:
            idempotencyKey,
        }),
      }
    );

  const text =
    await response.text();

  let result = null;

  try {
    result = text
      ? JSON.parse(text)
      : null;
  } catch {
    result = null;
  }

  if (
    !response.ok ||
    !result ||
    result.ok !== true
  ) {
    console.error(
      "receiveFinancePurchaseApi failed:",
      response.status,
      result,
      text
    );

    throw new Error(
      result?.error ||
      `Не вдалося прийняти поставку (HTTP ${response.status}).`
    );
  }

  const data =
    result.data || {};

  if (
    data.purchase &&
    typeof data.purchase ===
      "object"
  ) {
    const currentPurchases =
      Array.isArray(
        state.financePurchases
      )
        ? state.financePurchases
        : [];

    const updatedPurchase =
      data.purchase;

    const purchaseExists =
      currentPurchases.some(
        (purchase) =>
          String(
            purchase?.id || ""
          ) ===
          cleanPurchaseId
      );

    state.financePurchases =
      purchaseExists
        ? currentPurchases.map(
            (purchase) =>
              String(
                purchase?.id || ""
              ) ===
              cleanPurchaseId
                ? {
                    ...purchase,
                    ...updatedPurchase,
                  }
                : purchase
          )
        : [
            updatedPurchase,
            ...currentPurchases,
          ];
  }

  if (
    typeof loadStockApi ===
    "function"
  ) {
    await loadStockApi(
      true
    );
  }

  return data;
}

function buildFinanceTrendChart(
  rows
) {
  const data =
    Array.isArray(rows)
      ? rows
      : [];

  if (!data.length) {
    return `
      <div class="financeChartEmpty">
        <span>⌁</span>

        <strong>
          За цей період ще немає операцій
        </strong>

        <p>
          Графік зʼявиться після першої
          фінансової операції.
        </p>
      </div>
    `;
  }

  const width = 820;
  const height = 250;

  const padLeft = 62;
  const padRight = 24;
  const padTop = 28;
  const padBottom = 42;

  const plotWidth =
    width -
    padLeft -
    padRight;

  const plotHeight =
    height -
    padTop -
    padBottom;

  const normalized =
    data.map(
      (row) => {
        const payments =
          Number(
            row.payments || 0
          );

        const expenses =
          Number(
            row.expenses || 0
          );

        const refunds =
          Number(
            row.refunds || 0
          );

        return {
          ...row,

          payments,

          outcome:
            expenses +
            refunds,
        };
      }
    );

  const maxValue =
    Math.max(
      1,

      ...normalized.map(
        (row) =>
          Math.max(
            row.payments,
            row.outcome
          )
      )
    );

  const yForValue =
    (value) => {
      return (
        padTop +
        (
          1 -
          Number(value || 0) /
          maxValue
        ) *
        plotHeight
      );
    };

  const baselineY =
    padTop +
    plotHeight;

  const groupStep =
    plotWidth /
    normalized.length;

  const barWidth =
    Math.min(
      30,
      Math.max(
        10,
        groupStep * 0.22
      )
    );

  const showValues =
    normalized.length <= 8;

  const grid =
    Array
      .from({
        length: 5,
      })
      .map(
        (
          _,
          index
        ) => {
          const value =
            maxValue *
            (
              1 -
              index / 4
            );

          const y =
            yForValue(
              value
            );

          return `
            <line
              class="financeCashflowGrid"
              x1="${padLeft}"
              y1="${y}"
              x2="${width - padRight}"
              y2="${y}"
            ></line>

            <text
              class="financeCashflowAxisLabel"
              x="${padLeft - 10}"
              y="${y + 3}"
              text-anchor="end"
            >
              ${Math.round(
                value
              ).toLocaleString(
                "uk-UA"
              )}
            </text>
          `;
        }
      )
      .join("");

  const groups =
    normalized
      .map(
        (
          row,
          index
        ) => {
          const x =
            padLeft +
            groupStep *
            (
              index +
              0.5
            );

          const incomeY =
            yForValue(
              row.payments
            );

          const outcomeY =
            yForValue(
              row.outcome
            );

          const incomeHeight =
            Math.max(
              0,
              baselineY -
              incomeY
            );

          const outcomeHeight =
            Math.max(
              0,
              baselineY -
              outcomeY
            );

          const rawDate =
            String(
              row.date || ""
            );

          let dateLabel =
            rawDate;

          try {
            dateLabel =
              new Date(
                `${rawDate}T00:00:00`
              )
                .toLocaleDateString(
                  "uk-UA",
                  {
                    day: "2-digit",
                    month: "2-digit",
                  }
                );
          } catch {
            dateLabel =
              rawDate;
          }

          const labelStep =
            Math.max(
              1,
              Math.ceil(
                normalized.length /
                6
              )
            );

          const showDate =
            index %
              labelStep ===
              0 ||
            index ===
              normalized.length - 1;

          return `
            <g class="financeCashflowGroup">
              ${
                row.payments > 0
                  ? `
                    <rect
                      class="financeIncomeBar"
                      x="${
                        x -
                        barWidth -
                        3
                      }"
                      y="${incomeY}"
                      width="${barWidth}"
                      height="${incomeHeight}"
                      rx="6"
                    >
                      <title>
                        ${escapeHtml(rawDate)}

                        Надходження:
                        ${formatVisitFinanceMoney(
                          row.payments
                        )}
                      </title>
                    </rect>

                    ${
                      showValues
                        ? `
                          <text
                            class="financeCashflowValueLabel is-income"
                            x="${
                              x -
                              barWidth / 2 -
                              3
                            }"
                            y="${
                              Math.max(
                                padTop + 9,
                                incomeY - 8
                              )
                            }"
                            text-anchor="middle"
                          >
                            ${Math.round(
                              row.payments
                            ).toLocaleString(
                              "uk-UA"
                            )}
                          </text>
                        `
                        : ""
                    }
                  `
                  : ""
              }

              ${
                row.outcome > 0
                  ? `
                    <rect
                      class="financeOutcomeBar"
                      x="${x + 3}"
                      y="${outcomeY}"
                      width="${barWidth}"
                      height="${outcomeHeight}"
                      rx="6"
                    >
                      <title>
                        ${escapeHtml(rawDate)}

                        Витрати:
                        ${formatVisitFinanceMoney(
                          row.outcome
                        )}
                      </title>
                    </rect>

                    ${
                      showValues
                        ? `
                          <text
                            class="financeCashflowValueLabel is-outcome"
                            x="${
                              x +
                              barWidth / 2 +
                              3
                            }"
                            y="${
                              Math.max(
                                padTop + 9,
                                outcomeY - 8
                              )
                            }"
                            text-anchor="middle"
                          >
                            ${Math.round(
                              row.outcome
                            ).toLocaleString(
                              "uk-UA"
                            )}
                          </text>
                        `
                        : ""
                    }
                  `
                  : ""
              }

              ${
                showDate
                  ? `
                    <text
                      class="financeCashflowDateLabel"
                      x="${x}"
                      y="${height - 13}"
                      text-anchor="middle"
                    >
                      ${escapeHtml(
                        dateLabel
                      )}
                    </text>
                  `
                  : ""
              }
            </g>
          `;
        }
      )
      .join("");

  return `
    <div class="financeChartCanvas">
      <div class="financeCashflowLegend">
        <span>
          <i class="is-income"></i>
          Надходження
        </span>

        <span>
          <i class="is-outcome"></i>
          Витрати
        </span>
      </div>

      <svg
        viewBox="0 0 ${width} ${height}"
        role="img"
        aria-label="Надходження та витрати клініки"
      >
        ${grid}

        <line
          class="financeCashflowZeroLine"
          x1="${padLeft}"
          y1="${baselineY}"
          x2="${width - padRight}"
          y2="${baselineY}"
        ></line>

        ${groups}
      </svg>
    </div>
  `;
}

function getFinanceTransactionMeta(
  transaction
) {
  const methods = {
    cash:
      "Готівка",

    card:
      "Картка / термінал",

    terminal:
      "Картка / термінал",

    transfer:
      "Переказ",

    other:
      "Інше",
  };

  const types = {
    payment: {
      icon: "↗",
      label: "Оплата",
      className:
        "is-income",
    },

    refund: {
      icon: "↙",
      label: "Повернення",
      className:
        "is-outcome",
    },

    expense: {
      icon: "−",
      label: "Витрата",
      className:
        "is-outcome",
    },

    deposit: {
      icon: "+",
      label: "Внесення",
      className:
        "is-income",
    },

    withdrawal: {
      icon: "−",
      label: "Вилучення",
      className:
        "is-outcome",
    },
  };

  return {
    method:
      methods[
        transaction
          .payment_method
      ] ||
      "Інше",

    type:
      types[
        transaction
          .transaction_type
      ] || {
        icon: "•",

        label:
          transaction
            .transaction_type ||
          "Операція",

        className: "",
      },
  };
}
