addSupplierButton.addEventListener(
  "click",
  () => {
    openFinanceSupplierCreateModal(
      async (
        supplier
      ) => {
        if (
          !supplier?.id
        ) {
          return;
        }

        const option =
          document.createElement(
            "option"
          );

        option.value =
          supplier.id;

        option.textContent =
          supplier.name ||
          "Новий постачальник";

        supplierSelect.appendChild(
          option
        );

        supplierSelect.value =
          supplier.id;

        submitButton.disabled =
          false;

        overlay
          .querySelector(
            ".financePurchaseNoSuppliers"
          )
          ?.remove();
      }
    );
  }
);
    let rowCounter = 0;
    let submitting = false;

    const updateTotals = () => {
      const rows = [
        ...itemsList.querySelectorAll(
          ".financePurchaseCreateItem"
        ),
      ];

      const subtotal =
        rows.reduce(
          (
            total,
            row
          ) => {
            const quantity =
              Math.max(
                0,
                Number(
                  row.querySelector(
                    '[name="ordered_qty"]'
                  )?.value ||
                  0
                )
              );

            const price =
              Math.max(
                0,
                Number(
                  row.querySelector(
                    '[name="purchase_price"]'
                  )?.value ||
                  0
                )
              );

            const lineTotal =
              quantity * price;

            const lineElement =
              row.querySelector(
                ".financePurchaseItemLineTotal"
              );

            if (lineElement) {
              lineElement.textContent =
                formatVisitFinanceMoney(
                  lineTotal
                );
            }

            return (
              total +
              lineTotal
            );
          },
          0
        );

      const discount =
        Math.max(
          0,
          Number(
            form.elements
              .discount_amount
              ?.value ||
            0
          )
        );

      const total =
        Math.max(
          0,
          subtotal -
          discount
        );

      overlay.querySelector(
        "#financePurchaseCreateSubtotal"
      ).textContent =
        formatVisitFinanceMoney(
          subtotal
        );

      overlay.querySelector(
        "#financePurchaseCreateDiscount"
      ).textContent =
        formatVisitFinanceMoney(
          discount
        );

      overlay.querySelector(
        "#financePurchaseCreateTotal"
      ).textContent =
        formatVisitFinanceMoney(
          total
        );
    };

