function a4FilenameFromVisit(visitId) {
  const v = getVisitByIdSync(visitId) || {};
  const date = String(v.date || todayISO());
  return `DocPUG_${date}_visit_${String(visitId)}.pdf`;
}

function collectPatientDocumentBreakRanges(
  documentNode,
  canvasWidth
) {
  const documentRect =
    documentNode?.getBoundingClientRect();

  if (
    !documentRect ||
    !documentRect.width ||
    !canvasWidth
  ) {
    return [];
  }

  const scale =
    canvasWidth / documentRect.width;

  const selectors = [
    ".disModernHead",
    ".disModernInfoGrid",
    ".disModernSection",
    ".disModernTextLine",
    ".disModernFinanceHead",
    ".disModernFinanceSummary",
    ".disModernTable tr",
    ".disModernSignGrid",
    ".disConsentRepresentative",
    ".disConsentClause",
    ".disConsentDataSection",
    ".disConsentAcknowledgements",
    ".disConsentSignGrid",
    ".disModernFooter",
  ].join(",");

  return Array.from(
    documentNode.querySelectorAll(
      selectors
    )
  )
    .map((element) => {
      const rect =
        element.getBoundingClientRect();

      return {
        top: Math.max(
          0,
          Math.round(
            (
              rect.top -
              documentRect.top
            ) * scale
          )
        ),
        bottom: Math.max(
          0,
          Math.round(
            (
              rect.bottom -
              documentRect.top
            ) * scale
          )
        ),
      };
    })
    .filter(
      (range) =>
        range.bottom >
        range.top
    );
}

function choosePatientDocumentSliceHeight({
  sourceY,
  idealSliceHeight,
  canvasHeight,
  breakRanges,
}) {
  const idealEnd =
    Math.min(
      sourceY + idealSliceHeight,
      canvasHeight
    );

  if (idealEnd >= canvasHeight) {
    return canvasHeight - sourceY;
  }

  const minimumFill =
    idealSliceHeight * 0.42;

  const candidate =
    (breakRanges || [])
      .filter((range) => {
        const height =
          range.bottom - range.top;

        return (
          range.top >
            sourceY +
            minimumFill &&
          range.top <
            idealEnd - 4 &&
          range.bottom >
            idealEnd + 2 &&
          height <
            idealSliceHeight * 0.92
        );
      })
      .sort((a, b) => {
        const heightA =
          a.bottom - a.top;
        const heightB =
          b.bottom - b.top;

        return heightB - heightA;
      })[0];

  if (!candidate) {
    return idealEnd - sourceY;
  }

  return Math.max(
    1,
    candidate.top - sourceY
  );
}

async function downloadA4Pdf(
  visitId,
  options = {}
) {
  if (
    typeof window.html2canvas === "undefined" &&
    typeof window.html2pdf === "undefined"
  ) {
    alert("Модуль формування PDF не підключений.");
    return;
  }

  const JsPdfConstructor =
    window.jspdf?.jsPDF ||
    window.jsPDF;

  if (!JsPdfConstructor) {
    alert("Модуль jsPDF не підключений.");
    return;
  }

  if (options.render !== false) {
    await renderDischargeA4(visitId);
  }

  const sourceHost =
    document.getElementById("disA4");

  const sourceDocument =
    sourceHost?.querySelector(".disModernDoc");

  if (!sourceDocument) {
    alert("Не вдалося сформувати виписку.");
    return;
  }

  /*
   * Создаём независимую копию документа.
   * Размер 794 px соответствует A4 при 96 dpi.
   */
  const renderHost =
    document.createElement("div");

  renderHost.id =
    "visitPdfRenderHost";

  renderHost.style.cssText = `
    position: fixed;
    left: 0;
    top: 0;

    width: 794px;
    min-width: 794px;
    max-width: 794px;

    margin: 0;
    padding: 0;

    display: block;
    visibility: visible;
    opacity: 1;

    background: #ffffff;
    overflow: visible;

    pointer-events: none;
    z-index: 2147483647;

    transform: none;
    box-sizing: border-box;
  `;

  const pdfDocument =
    sourceDocument.cloneNode(true);

  pdfDocument.style.cssText += `
    position: relative !important;
    left: 0 !important;
    top: 0 !important;

    width: 794px !important;
    min-width: 794px !important;
    max-width: 794px !important;

    margin: 0 !important;
    padding: 24px !important;

    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;

    background: #ffffff !important;
    color: #1f2937 !important;

    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;

    overflow: visible !important;
    transform: none !important;

    box-sizing: border-box !important;
  `;

  renderHost.appendChild(
    pdfDocument
  );

  document.body.appendChild(
    renderHost
  );

  try {
    if (document.fonts?.ready) {
      await document.fonts.ready;
    }

    await new Promise((resolve) => {
      requestAnimationFrame(() => {
        requestAnimationFrame(resolve);
      });
    });

    const images = Array.from(
      pdfDocument.querySelectorAll("img")
    );

    await Promise.all(
      images.map((image) => {
        if (
          image.complete &&
          image.naturalWidth > 0
        ) {
          return Promise.resolve();
        }

        return new Promise((resolve) => {
          const finish = () => resolve();

          image.addEventListener(
            "load",
            finish,
            { once: true }
          );

          image.addEventListener(
            "error",
            finish,
            { once: true }
          );

          setTimeout(finish, 4000);
        });
      })
    );

    /*
     * html2pdf bundle обычно содержит html2canvas,
     * но на всякий случай получаем его обоими способами.
     */
    const html2canvasFunction =
      window.html2canvas ||
      window.html2pdf?.Worker?.prototype
        ?.prop?.html2canvas;

    if (
      typeof html2canvasFunction !==
      "function"
    ) {
      alert("Модуль html2canvas не підключений.");
      return;
    }

    const canvas =
      await html2canvasFunction(
        pdfDocument,
        {
          scale: 2,
          useCORS: true,
          allowTaint: false,
          backgroundColor: "#ffffff",
          logging: false,

          scrollX: 0,
          scrollY: 0,

          width: 794,
          windowWidth: 794,

          onclone: (
            clonedDocument
          ) => {
            const clonedHost =
              clonedDocument.getElementById(
                "visitPdfRenderHost"
              );

            if (clonedHost) {
              clonedHost.style.position =
                "absolute";

              clonedHost.style.left = "0";
              clonedHost.style.top = "0";

              clonedHost.style.width =
                "794px";

              clonedHost.style.minWidth =
                "794px";

              clonedHost.style.maxWidth =
                "794px";

              clonedHost.style.margin = "0";
              clonedHost.style.padding = "0";

              clonedHost.style.display =
                "block";

              clonedHost.style.visibility =
                "visible";

              clonedHost.style.opacity = "1";

              clonedHost.style.transform =
                "none";

              clonedHost.style.background =
                "#ffffff";
            }

            const clonedDocumentNode =
              clonedHost?.querySelector(
                ".disModernDoc"
              );

            if (clonedDocumentNode) {
              clonedDocumentNode.style.position =
                "relative";

              clonedDocumentNode.style.left =
                "0";

              clonedDocumentNode.style.top =
                "0";

              clonedDocumentNode.style.width =
                "794px";

              clonedDocumentNode.style.minWidth =
                "794px";

              clonedDocumentNode.style.maxWidth =
                "794px";

              clonedDocumentNode.style.margin =
                "0";

              clonedDocumentNode.style.padding =
                "24px";

              clonedDocumentNode.style.display =
                "block";

              clonedDocumentNode.style.visibility =
                "visible";

              clonedDocumentNode.style.opacity =
                "1";

              clonedDocumentNode.style.transform =
                "none";

              clonedDocumentNode.style.borderRadius =
                "0";

              clonedDocumentNode.style.boxShadow =
                "none";

              clonedDocumentNode.style.background =
                "#ffffff";

              clonedDocumentNode.style.boxSizing =
                "border-box";

              clonedDocumentNode.style.overflow =
                "visible";
            }
          },
        }
      );

    if (
      !canvas ||
      canvas.width < 100 ||
      canvas.height < 100
    ) {
      throw new Error(
        "Документ не вдалося перетворити на зображення"
      );
    }

    /*
     * A4:
     * 210 × 297 мм.
     * Оставляем поля по 8 мм.
     */
    const pdf =
      new JsPdfConstructor({
        orientation: "portrait",
        unit: "mm",
        format: "a4",
        compress: true,
      });

    const pageWidthMm = 210;
    const pageHeightMm = 297;

    const marginLeftMm = 8;
    const marginTopMm = 8;
    const marginRightMm = 8;
    const marginBottomMm = 8;

    const contentWidthMm =
      pageWidthMm -
      marginLeftMm -
      marginRightMm;

    const contentHeightMm =
      pageHeightMm -
      marginTopMm -
      marginBottomMm;

    /*
     * Сколько пикселей исходного canvas
     * помещается на одной странице A4.
     */
    const pageSliceHeightPx =
      Math.floor(
        canvas.width *
        (
          contentHeightMm /
          contentWidthMm
        )
      );

    const breakRanges =
      collectPatientDocumentBreakRanges(
        pdfDocument,
        canvas.width
      );

    let sourceY = 0;
    let pageIndex = 0;

    while (sourceY < canvas.height) {
      const sliceHeight =
        choosePatientDocumentSliceHeight({
          sourceY,
          idealSliceHeight:
            pageSliceHeightPx,
          canvasHeight:
            canvas.height,
          breakRanges,
        });

      const pageCanvas =
        document.createElement("canvas");

      pageCanvas.width =
        canvas.width;

      pageCanvas.height =
        sliceHeight;

      const context =
        pageCanvas.getContext("2d");

      if (!context) {
        throw new Error(
          "Не вдалося створити сторінку PDF"
        );
      }

      context.fillStyle = "#ffffff";

      context.fillRect(
        0,
        0,
        pageCanvas.width,
        pageCanvas.height
      );

      context.drawImage(
        canvas,

        0,
        sourceY,
        canvas.width,
        sliceHeight,

        0,
        0,
        pageCanvas.width,
        sliceHeight
      );

      const pageImage =
        pageCanvas.toDataURL(
          "image/jpeg",
          0.98
        );

      const renderedHeightMm =
        contentWidthMm *
        (
          sliceHeight /
          canvas.width
        );

      if (pageIndex > 0) {
        pdf.addPage();
      }

      pdf.addImage(
        pageImage,
        "JPEG",
        marginLeftMm,
        marginTopMm,
        contentWidthMm,
        renderedHeightMm,
        undefined,
        "FAST"
      );

      sourceY += sliceHeight;
      pageIndex += 1;
    }

    pdf.save(
      options.filename ||
      a4FilenameFromVisit(visitId)
    );
  } catch (error) {
    console.error(
      "downloadA4Pdf failed:",
      error
    );

    alert(
      "Не вдалося сформувати PDF: " +
      (
        error?.message ||
        error
      )
    );
  } finally {
    renderHost.remove();
  }
}

function printA4Only(visitId) {
  ensurePrintCss();
  setDischarge(visitId, readDischargeForm());
  renderDischargeA4(visitId);

  document.body.classList.add("docpug-printing");
  setTimeout(() => {
    window.print();
    setTimeout(() => document.body.classList.remove("docpug-printing"), 300);
  }, 50);
}

