function canEditPatientDiagnoses() {
  return [
    "owner",
    "admin",
    "vet",
  ].includes(
    String(
      state.me?.role || ""
    ).trim().toLowerCase()
  );
}

async function patientDiagnosisRequest(
  url,
  options = {}
) {
  const response = await fetch(url, {
    credentials: "include",
    ...options,
    headers: {
      Accept: "application/json",
      ...getOrgHeaders(),
      ...(options.body
        ? {
            "Content-Type":
              "application/json",
          }
        : {}),
      ...(options.headers || {}),
    },
  });

  const result = await response
    .json()
    .catch(() => null);

  if (!response.ok || !result?.ok) {
    const error = new Error(
      result?.error ||
      "Не вдалося виконати медичну дію."
    );
    error.status = response.status;
    throw error;
  }

  return result.data;
}

async function loadPatientDiagnosesApi(
  patientId,
  scope = "active"
) {
  try {
    const data =
      await patientDiagnosisRequest(
        `/api/patients/${encodeURIComponent(
          String(patientId)
        )}/diagnoses?scope=${encodeURIComponent(
          scope
        )}`
      );

    return Array.isArray(data)
      ? data
      : [];
  } catch (error) {
    console.error(
      "loadPatientDiagnosesApi failed:",
      error
    );
    return null;
  }
}

async function createPatientDiagnosisApi(
  patientId,
  payload
) {
  return patientDiagnosisRequest(
    `/api/patients/${encodeURIComponent(
      String(patientId)
    )}/diagnoses`,
    {
      method: "POST",
      body: JSON.stringify(payload),
    }
  );
}

async function updatePatientDiagnosisApi(
  diagnosisId,
  payload
) {
  return patientDiagnosisRequest(
    `/api/patient-diagnoses/${encodeURIComponent(
      String(diagnosisId)
    )}`,
    {
      method: "PUT",
      body: JSON.stringify(payload),
    }
  );
}

async function loadPatientDiagnosisEventsApi(
  diagnosisId
) {
  const data =
    await patientDiagnosisRequest(
      `/api/patient-diagnoses/${encodeURIComponent(
        String(diagnosisId)
      )}/events`
    );

  return Array.isArray(data)
    ? data
    : [];
}

function sortPatientDiagnoses(
  diagnoses
) {
  const severityOrder = {
    critical: 0,
    severe: 1,
    moderate: 2,
    mild: 3,
  };

  return [...(
    Array.isArray(diagnoses)
      ? diagnoses
      : []
  )].sort((left, right) => {
    const severityDifference =
      (
        severityOrder[left?.severity] ?? 4
      ) -
      (
        severityOrder[right?.severity] ?? 4
      );

    if (severityDifference) {
      return severityDifference;
    }

    return String(
      right?.diagnosed_at || ""
    ).localeCompare(
      String(
        left?.diagnosed_at || ""
      )
    );
  });
}

function formatPatientDiagnosisDate(
  value
) {
  if (!value) return "Дата не вказана";

  const parsed = new Date(value);

  if (Number.isNaN(parsed.getTime())) {
    return escapeHtml(
      String(value).slice(0, 10)
    );
  }

  return parsed.toLocaleDateString(
    "uk-UA",
    {
      day: "2-digit",
      month: "short",
      year: "numeric",
    }
  );
}

