function renderPatientWeightPanel(
  pet,
  history = []
) {
  const rows =
    Array.isArray(history)
      ? [...history]
      : [];

  const sorted =
    rows.sort(
      (a, b) =>
        String(
          b.measured_at ||
          b.created_at ||
          ""
        ).localeCompare(
          String(
            a.measured_at ||
            a.created_at ||
            ""
          )
        )
    );

  const latest =
    sorted[0] || null;

  const currentWeight =
    Number(
      latest?.weight_kg ??
      pet?.weight_kg ??
      0
    );

  const previousWeight =
    Number(
      sorted[1]?.weight_kg ||
      0
    );

  let difference = null;

  if (
    currentWeight > 0 &&
    previousWeight > 0
  ) {
    difference =
      currentWeight -
      previousWeight;
  }

  const recent =
    sorted.slice(
      0,
      4
    );

  return `
    <section class="patientWeightPanel">

      <header class="patientWeightHeader">
        <div>
          <h3>
            Динаміка ваги
          </h3>

          <p>
            Історія вимірювань маси тіла пацієнта.
          </p>
        </div>

        <button
          type="button"
          class="patientWeightAdd"
          data-add-patient-weight
        >
          + Додати вагу
        </button>
      </header>

      <div class="patientWeightBody">

        <div class="patientWeightCurrent">

          <span>
            Поточна вага
          </span>

          <strong>
            ${
              currentWeight > 0
                ? `${currentWeight.toLocaleString(
                    "uk-UA",
                    {
                      maximumFractionDigits:
                        3,
                    }
                  )} кг`
                : "—"
            }
          </strong>

          ${
            difference !== null
              ? `
                <small
                  class="${
                    difference > 0
                      ? "is-up"
                      : difference < 0
                        ? "is-down"
                        : "is-stable"
                  }"
                >
                  ${
                    difference > 0
                      ? "↑"
                      : difference < 0
                        ? "↓"
                        : "•"
                  }

                  ${Math.abs(
                    difference
                  ).toLocaleString(
                    "uk-UA",
                    {
                      maximumFractionDigits:
                        3,
                    }
                  )} кг

                  від попереднього
                  вимірювання
                </small>
              `
              : `
                <small>
                  Немає попереднього
                  вимірювання
                </small>
              `
          }

        </div>

        <div class="patientWeightHistory">

          ${
            recent.length
              ? recent
                  .map(
                    (item) => {
                      const date =
                        item.measured_at ||
                        item.created_at ||
                        "";

                      const dateLabel =
                        date
                          ? new Date(
                              date
                            ).toLocaleDateString(
                              "uk-UA",
                              {
                                day:
                                  "2-digit",
                                month:
                                  "2-digit",
                                year:
                                  "numeric",
                              }
                            )
                          : "—";

                      return `
                        <div class="patientWeightRow">

                          <span>
                            ${escapeHtml(
                              dateLabel
                            )}
                          </span>

                          <strong>
                            ${Number(
                              item.weight_kg ||
                              0
                            ).toLocaleString(
                              "uk-UA",
                              {
                                maximumFractionDigits:
                                  3,
                              }
                            )}
                            кг
                          </strong>

                        </div>
                      `;
                    }
                  )
                  .join("")
              : `
                <div class="patientWeightEmpty">
                  Історії ваги поки немає.
                </div>
              `
          }

        </div>

      </div>

    </section>
  `;
}

