function getPatientDocumentVisitLabel(
  visit
) {
  const parsed =
    typeof parseVisitNote === "function"
      ? parseVisitNote(visit?.note || "")
      : { dx: "" };

  const diagnosis =
    String(
      visit?.dx ||
      parsed.dx ||
      ""
    ).trim();

  const serviceNames =
    typeof expandServiceLines === "function"
      ? expandServiceLines(visit)
          .slice(0, 2)
          .map((line) => line.name)
          .filter(Boolean)
      : [];

  const description =
    diagnosis ||
    serviceNames.join(", ") ||
    "Прийом";

  return [
    formatPatientDocumentDate(
      visit?.date ||
      visit?.created_at
    ),
    description,
  ].join(" — ");
}

async function loadPatientHospitalizationsApi(
  patientId
) {
  try {
    const response = await fetch(
      `/api/hospitalizations?patient_id=${encodeURIComponent(
        String(patientId)
      )}`,
      {
        credentials: "include",
        headers: {
          Accept: "application/json",
          ...getOrgHeaders(),
        },
      }
    );

    const result =
      await response
        .json()
        .catch(() => null);

    if (
      !response.ok ||
      !result?.ok
    ) {
      return [];
    }

    return Array.isArray(result.data)
      ? result.data
      : [];
  } catch (error) {
    console.error(
      "loadPatientHospitalizationsApi failed:",
      error
    );

    return [];
  }
}

