async function renderPatientDocumentsTab(
  root,
  pet
) {
  if (!root || !pet) return;

  root.innerHTML = `
    <div class="patientDocumentsLoading">
      Підготовка документів…
    </div>
  `;

  /*
   * Не запускаем два тяжёлых Supabase-чтения одновременно.
   * На небольшом серверном инстансе параллельный старт мог
   * временно исчерпать сетевые ресурсы и вернуть Errno 11.
   */
  const visits =
    await loadVisitsApi({
      pet_id: pet.id,
    });

  const hospitalizations =
    await loadPatientHospitalizationsApi(
      pet.id
    );

  const patientVisits =
    (Array.isArray(visits)
      ? visits
      : []
    ).sort((a, b) =>
      String(
        b.date ||
        b.created_at ||
        ""
      ).localeCompare(
        String(
          a.date ||
          a.created_at ||
          ""
        )
      )
    );

  const completedHospitalizations =
    (Array.isArray(hospitalizations)
      ? hospitalizations
      : []
    )
      .filter(
        (item) =>
          item?.is_active === false ||
          Boolean(item?.discharged_at)
      )
      .sort((a, b) =>
        String(
          b.discharged_at ||
          b.admitted_at ||
          ""
        ).localeCompare(
          String(
            a.discharged_at ||
            a.admitted_at ||
            ""
          )
        )
      );

  const visitOptions =
    patientVisits.map((visit) => ({
      value: visit.id,
      label:
        getPatientDocumentVisitLabel(
          visit
        ),
    }));

  const hospitalOptions =
    completedHospitalizations.map(
      (item) => ({
        value: item.id,
        label: [
          formatPatientDocumentDate(
            item.admitted_at
          ),
          "—",
          formatPatientDocumentDate(
            item.discharged_at
          ),
          item.diagnosis
            ? `· ${item.diagnosis}`
            : "",
        ]
          .filter(Boolean)
          .join(" "),
      })
    );

  const consentOptions =
    Object.entries(
      PATIENT_CONSENT_TYPES
    ).map(([value, config]) => ({
      value,
      label: config.shortTitle,
    }));

  root.innerHTML = `
    <section class="patientDocumentsPage">
      <header class="patientDocumentsHead">
        <div>
          <div class="patientDocumentsKicker">
            ДОКУМЕНТИ ПАЦІЄНТА
          </div>

          <h2>
            Медичні та фінансові документи
          </h2>

          <p>
            Оберіть джерело — CRM автоматично
            сформує окремий PDF без повторного
            введення даних.
          </p>
        </div>

        <div class="patientDocumentsSummary">
          <span>Доступно джерел</span>
          <strong>
            ${
              patientVisits.length +
              completedHospitalizations.length
            }
          </strong>
          <small>
            ${patientVisits.length} візитів ·
            ${completedHospitalizations.length}
            виписок зі стаціонару
          </small>
        </div>
      </header>

      <div class="patientDocumentsGrid">
        ${renderPatientDocumentCard({
          type: "visit",
          icon: "🩺",
          title:
            "Виписка за візитом",
          description:
            "Медичний підсумок прийому: скарги, діагноз, проведені процедури та рекомендації — без цін.",
          badge: "МЕДИЧНИЙ",
          options: visitOptions,
          selectLabel: "Оберіть візит",
          emptyText:
            "У пацієнта ще немає візитів.",
        })}

        ${renderPatientDocumentCard({
          type: "hospital",
          icon: "🏥",
          title:
            "Виписка зі стаціонару",
          description:
            "Період госпіталізації, діагноз, стан, виконані процедури й призначення та стан на момент виписки.",
          badge: "СТАЦІОНАР",
          options: hospitalOptions,
          selectLabel:
            "Оберіть госпіталізацію",
          emptyText:
            "Немає завершених госпіталізацій.",
        })}

        ${renderPatientDocumentCard({
          type: "prescriptions",
          icon: "💊",
          title:
            "Лист призначень",
          description:
            "Окремий зрозумілий документ з лікуванням, рекомендаціями власнику та планом контролю.",
          badge: "ДЛЯ ВЛАСНИКА",
          options: visitOptions,
          selectLabel: "Оберіть візит",
          emptyText:
            "Спочатку створіть візит.",
        })}

        ${renderPatientDocumentCard({
          type: "finance",
          icon: "🧾",
          title:
            "Фінансова виписка",
          description:
            "Деталізація наданих послуг, використаних препаратів, знижки, оплат і залишку.",
          badge: "ФІНАНСОВИЙ",
          options: visitOptions,
          selectLabel: "Оберіть візит",
          emptyText:
            "Немає візитів для деталізації.",
        })}

        ${renderPatientDocumentCard({
          type: "consent",
          icon: "✍️",
          title:
            "Інформована згода",
          description:
            "Чотири окремі шаблони: лікування, операція й анестезія, госпіталізація та відмова від операції.",
          badge: "4 ШАБЛОНИ",
          options: consentOptions,
          selectLabel:
            "Оберіть тип документа",
          emptyText:
            "Шаблони недоступні.",
        })}
      </div>

      <div class="patientDocumentsHint">
        <span>ⓘ</span>
        Документи формуються з актуальних
        даних CRM. Завантажена копія не
        змінює медичну карту пацієнта.
      </div>
    </section>
  `;

  root
    .querySelectorAll(
      "[data-create-patient-document]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        async () => {
          const type =
            button.dataset
              .createPatientDocument;

          const select =
            root.querySelector(
              `[data-patient-document-source="${type}"]`
            );

          const sourceId =
            select?.value || "";

          if (!sourceId) return;

          const original =
            button.innerHTML;

          button.disabled = true;
          button.textContent =
            "Формування…";

          try {
            let consentData = null;

            if (type === "consent") {
              consentData =
                await openPatientConsentModal({
                  consentType: sourceId,
                  pet,
                  visits: patientVisits,
                });

              if (!consentData) {
                return;
              }
            }

            await createPatientDocumentPdf({
              type,
              sourceId,
              pet,
              visits: patientVisits,
              hospitalizations:
                completedHospitalizations,
              consentData,
            });
          } catch (error) {
            console.error(
              "createPatientDocumentPdf failed:",
              error
            );

            alert(
              error?.message ||
              "Не вдалося сформувати документ."
            );
          } finally {
            button.disabled = false;
            button.innerHTML = original;
          }
        }
      );
    });
}

async function getPatientDocumentClinic() {
  let org =
    state.clinicProfile ||
    null;

  if (
    !org &&
    typeof loadClinicProfileApi ===
      "function"
  ) {
    org =
      await loadClinicProfileApi();
  }

  return org || {};
}

function patientConsentLocalDateTime(
  value = new Date()
) {
  const date =
    value instanceof Date
      ? value
      : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const offset =
    date.getTimezoneOffset() *
    60000;

  return new Date(
    date.getTime() - offset
  )
    .toISOString()
    .slice(0, 16);
}

function getPatientConsentVisitDefaults(
  visit
) {
  if (!visit) {
    return {
      diagnosis: "",
      subject: "",
      notes: "",
    };
  }

  const parsedNote =
    typeof parseVisitNote ===
      "function"
      ? parseVisitNote(
          visit.note || ""
        )
      : {};

  const services =
    typeof expandServiceLines ===
      "function"
      ? expandServiceLines(visit)
      : [];

  return {
    diagnosis:
      String(
        visit.dx ||
        parsedNote.dx ||
        ""
      ).trim(),
    subject:
      services
        .map((line) => line.name)
        .filter(Boolean)
        .join(", "),
    notes: "",
  };
}

