function createPatientConsentDocumentHtml({
  consentData,
  pet,
  owner,
  clinic,
  visits,
}) {
  const config =
    PATIENT_CONSENT_TYPES[
      consentData?.consentType
    ];

  if (!config) {
    throw new Error(
      "Невідомий тип згоди."
    );
  }

  const visit =
    (visits || []).find(
      (item) =>
        String(item.id) ===
        String(
          consentData.visitId ||
          ""
        )
    ) || null;

  const doctorName =
    getPatientDocumentDoctorName(
      visit || {}
    );

  const representativeName =
    consentData
      .representativeName ||
    owner?.name ||
    "—";

  const representativePhone =
    consentData
      .representativePhone ||
    owner?.phone ||
    "—";

  const clauses =
    getPatientConsentClauses(
      consentData.consentType,
      consentData.subject
    );

  const documentSeed =
    String(
      consentData.signedAt ||
      Date.now()
    )
      .replace(/\D/g, "")
      .slice(-10);

  const clauseHtml =
    clauses
      .map(
        (clause) => `
          <li class="disConsentClause">
            ${escapeHtml(clause)}
          </li>
        `
      )
      .join("");

  const body = `
    <div class="disConsentRepresentative">
      <div>
        <span>ПРЕДСТАВНИК</span>
        <strong>${escapeHtml(
          representativeName
        )}</strong>
      </div>
      <div>
        <span>СТАТУС</span>
        <strong>${escapeHtml(
          consentData
            .representativeRole ||
          "Власник тварини"
        )}</strong>
      </div>
      <div>
        <span>ТЕЛЕФОН</span>
        <strong>${escapeHtml(
          representativePhone
        )}</strong>
      </div>
    </div>

    ${renderPatientDocumentSection(
      config.subjectLabel,
      consentData.subject,
      true
    )}

    ${renderPatientDocumentSection(
      config.detailsLabel,
      consentData.diagnosis
    )}

    ${
      consentData.notes
        ? renderPatientDocumentSection(
            "Індивідуальні ризики та додаткові умови",
            consentData.notes
          )
        : ""
    }

    <div class="disModernSection disConsentSection">
      <div class="disModernSectionTitle">
        Підтвердження поінформованого рішення
      </div>

      <p class="disConsentLead">
        Я, ${escapeHtml(
          representativeName
        )}, підтверджую, що маю право
        приймати рішення щодо ветеринарної
        допомоги пацієнту
        ${escapeHtml(pet?.name || "—")}.
        Інформацію надано зрозумілою мовою,
        я мав/мала можливість поставити
        запитання та отримати відповіді.
      </p>

      <ol class="disConsentClauses">
        ${clauseHtml}
      </ol>
    </div>

    <div class="disModernSection disConsentDataSection">
      <div class="disModernSectionTitle">
        Обробка персональних даних
      </div>

      <p class="disConsentLead">
        Надаю добровільну документовану згоду
        на обробку зазначених у цьому документі
        контактних та ідентифікаційних даних
        виключно для оформлення цієї згоди,
        ведення медичної і фінансової історії
        пацієнта та зв’язку щодо лікування.
        Мене повідомлено про право звернутися
        для доступу, уточнення або виправлення
        даних та відкликати згоду в межах,
        установлених законодавством.
      </p>
    </div>

    <div class="disConsentAcknowledgements">
      <div>
        <span>✓</span>
        Повноваження представника підтверджено
      </div>
      <div>
        <span>✓</span>
        Пояснення лікаря отримано
      </div>
      <div>
        <span>✓</span>
        Згоду на обробку даних надано
      </div>
    </div>
  `;

  return renderPatientDocumentShell({
    title: config.title,
    number:
      `${config.code}-${documentSeed || "DOC"}`,
    dateLabel:
      `Дата: ${
        formatPatientDocumentDate(
          consentData.signedAt,
          true
        )
      }`,
    pet,
    owner: {
      ...(owner || {}),
      name: representativeName,
      phone: representativePhone,
    },
    doctorName,
    clinic,
    body,
    signaturesHtml:
      renderPatientConsentSignatures({
        representativeName,
        doctorName,
        clinic,
        signedAt:
          consentData.signedAt,
      }),
  });
}

async function createPatientDocumentPdf({
  type,
  sourceId,
  pet,
  visits,
  hospitalizations,
  consentData = null,
}) {
  const owner =
    pet?.owner_id
      ? getOwnerById(
          pet.owner_id
        )
      : null;

  const clinic =
    await getPatientDocumentClinic();

  let html = "";
  let sourceDate = todayISO();

  if (type === "consent") {
    if (!consentData) {
      throw new Error(
        "Дані згоди не заповнені."
      );
    }

    sourceDate =
      consentData.signedAt ||
      sourceDate;

    html =
      createPatientConsentDocumentHtml({
        consentData,
        pet,
        owner,
        clinic,
        visits,
      });
  } else if (type === "hospital") {
    const hospitalization =
      hospitalizations.find(
        (item) =>
          String(item.id) ===
          String(sourceId)
      );

    if (!hospitalization) {
      throw new Error(
        "Госпіталізацію не знайдено."
      );
    }

    sourceDate =
      hospitalization.discharged_at ||
      hospitalization.admitted_at ||
      sourceDate;

    html =
      await createHospitalDocumentHtml({
        hospitalization,
        pet,
        owner,
        clinic,
      });
  } else {
    const visit =
      visits.find(
        (item) =>
          String(item.id) ===
          String(sourceId)
      );

    if (!visit) {
      throw new Error(
        "Візит не знайдено."
      );
    }

    sourceDate =
      visit.date ||
      visit.created_at ||
      sourceDate;

    html =
      await createVisitBasedDocumentHtml({
        type,
        visit,
        pet,
        owner,
        clinic,
      });
  }

  let host =
    document.getElementById(
      "disA4"
    );

  if (!host) {
    host =
      document.createElement(
        "div"
      );
    host.id = "disA4";
    host.className =
      "visitDischargePrintHost";
    document.body.appendChild(
      host
    );
  }

  host.innerHTML = html;

  const typeNames = {
    visit: "visit_discharge",
    hospital:
      "hospital_discharge",
    prescriptions:
      "prescriptions",
    finance:
      "financial_statement",
    consent:
      `consent_${
        consentData
          ?.consentType ||
        "document"
      }`,
  };

  const datePart =
    String(sourceDate)
      .slice(0, 10);

  const filename = [
    "DocPUG",
    sanitizePatientDocumentFilename(
      pet?.name ||
      "patient"
    ),
    typeNames[type] ||
      "document",
    datePart,
  ].join("_") + ".pdf";

  await downloadA4Pdf(
    null,
    {
      render: false,
      filename,
    }
  );
}

function renderPatientFinanceTab(root, pet) {
  if (!root || !pet) return;

  const petVisits = (
    Array.isArray(state.visits)
      ? state.visits
      : []
  )
    .filter((visit) => {
      return String(visit.pet_id) === String(pet.id);
    })
    .sort((a, b) => {
      return String(b.date || b.created_at || "")
        .localeCompare(
          String(a.date || a.created_at || "")
        );
    });

  const financialVisits = petVisits
    .map((visit) => {
      const servicesTotal =
        calcServicesTotal(visit);

      const stockTotal =
        calcStockTotal(visit);

      return {
        ...visit,
        servicesTotal,
        stockTotal,
        total:
          Number(servicesTotal || 0) +
          Number(stockTotal || 0),
      };
    });

  const paidVisits = financialVisits.filter((visit) => {
    return Number(visit.total || 0) > 0;
  });

  const totalPaid = paidVisits.reduce((sum, visit) => {
    return sum + Number(visit.total || 0);
  }, 0);

  const servicesTotal = paidVisits.reduce((sum, visit) => {
    return sum + Number(visit.servicesTotal || 0);
  }, 0);

  const stockTotal = paidVisits.reduce((sum, visit) => {
    return sum + Number(visit.stockTotal || 0);
  }, 0);

  const visitsCount = petVisits.length;

  const avgCheck = paidVisits.length
    ? Math.round(totalPaid / paidVisits.length)
    : 0;

  const lastPayment =
    paidVisits[0] || null;

  const topServices =
    buildPatientTopServices(petVisits, 5);

  const servicesPercent = totalPaid
    ? Math.round(
        (servicesTotal / totalPaid) * 100
      )
    : 0;

  const stockPercent = totalPaid
    ? Math.max(0, 100 - servicesPercent)
    : 0;

  const visitInterval =
    calculatePatientVisitInterval(petVisits);

  const insight = buildPatientFinanceInsight({
    pet,
    visitsCount,
    totalPaid,
    avgCheck,
    topServices,
    visitInterval,
  });

  root.innerHTML = `
    <section class="patientFinancePage">
      <div class="patientFinanceHead">
        <div>
          <div class="patientFinanceKicker">
            ФІНАНСОВА ІСТОРІЯ
          </div>

          <h2>Фінанси пацієнта</h2>

          <p>
            Коротка фінансова статистика
            ${escapeHtml(pet.name || "пацієнта")}
            без зайвої бухгалтерської деталізації.
          </p>
        </div>

        <div class="patientFinanceValueBadge">
          <span>Загальна цінність</span>
          <strong>
            ${formatPatientMoney(totalPaid)}
          </strong>
        </div>
      </div>

      <div class="patientFinanceKpis">
        ${renderPatientFinanceKpi({
          icon: "💳",
          label: "Усього сплачено",
          value: formatPatientMoney(totalPaid),
          note: `${paidVisits.length} оплат`,
          accent: true,
        })}

        ${renderPatientFinanceKpi({
          icon: "📊",
          label: "Середній чек",
          value: formatPatientMoney(avgCheck),
          note: "середнє за оплачений візит",
        })}

        ${renderPatientFinanceKpi({
          icon: "🐾",
          label: "Кількість візитів",
          value: String(visitsCount),
          note: getPatientVisitCountLabel(visitsCount),
        })}

        ${renderPatientFinanceKpi({
          icon: "🧾",
          label: "Остання оплата",
          value: lastPayment
            ? formatPatientMoney(lastPayment.total)
            : "—",
          note: lastPayment
            ? formatPatientFinanceDate(
                lastPayment.date ||
                lastPayment.created_at
              )
            : "оплат ще немає",
        })}
      </div>

      <div class="patientFinanceMainGrid">
        <section class="patientFinancePanel">
          <div class="patientFinancePanelHead">
            <div>
              <span class="patientFinancePanelIcon">
                ⭐
              </span>

              <div>
                <h3>Топ послуг</h3>
                <p>
                  Найчастіші та найцінніші послуги пацієнта.
                </p>
              </div>
            </div>

            <span class="patientFinanceSmallBadge">
              TOP 5
            </span>
          </div>

          <div class="patientTopServices">
            ${
              topServices.length
                ? topServices
                    .map((service, index) => {
                      return renderPatientTopService(
                        service,
                        index
                      );
                    })
                    .join("")
                : `
                  <div class="patientFinanceEmpty">
                    Послуги ще не додані до візитів.
                  </div>
                `
            }
          </div>
        </section>

        <section class="patientFinancePanel">
          <div class="patientFinancePanelHead">
            <div>
              <span class="patientFinancePanelIcon">
                ◔
              </span>

              <div>
                <h3>Структура витрат</h3>
                <p>
                  Співвідношення послуг та препаратів.
                </p>
              </div>
            </div>
          </div>

          <div class="patientExpenseTotal">
            <span>Загальні витрати</span>
            <strong>
              ${formatPatientMoney(totalPaid)}
            </strong>
          </div>

          <div class="patientExpenseBar">
            <i
              class="services"
              style="width:${servicesPercent}%"
            ></i>

            <i
              class="stock"
              style="width:${stockPercent}%"
            ></i>
          </div>

          <div class="patientExpenseLegend">
            <div>
              <span class="services"></span>

              <div>
                <small>Послуги</small>
                <strong>${servicesPercent}%</strong>
              </div>

              <b>
                ${formatPatientMoney(servicesTotal)}
              </b>
            </div>

            <div>
              <span class="stock"></span>

              <div>
                <small>Препарати</small>
                <strong>${stockPercent}%</strong>
              </div>

              <b>
                ${formatPatientMoney(stockTotal)}
              </b>
            </div>
          </div>
        </section>
      </div>

      <section class="patientFinancePanel patientPaymentsPanel">
        <div class="patientFinancePanelHead">
          <div>
            <span class="patientFinancePanelIcon">
              🧾
            </span>

            <div>
              <h3>Останні оплати</h3>
              <p>
                Візити з фактичною сумою до сплати.
              </p>
            </div>
          </div>

          ${
            paidVisits.length > 5
              ? `
                <button
                  class="patientPaymentsToggle"
                  id="btnTogglePatientPayments"
                  type="button"
                >
                  Показати всю історію
                </button>
              `
              : ""
          }
        </div>

        <div
          class="patientPaymentsList"
          id="patientPaymentsList"
        >
          ${
            paidVisits.length
              ? paidVisits
                  .map((visit, index) => {
                    return renderPatientPaymentRow(
                      visit,
                      index >= 5
                    );
                  })
                  .join("")
              : `
                <div class="patientFinanceEmpty">
                  Оплачених візитів поки немає.
                </div>
              `
          }
        </div>
      </section>

      <section class="patientFinanceInsight">
        <div class="patientFinanceInsightIcon">
          ✨
        </div>

        <div>
          <span>CRM-висновок</span>
          <p>${escapeHtml(insight)}</p>
        </div>
      </section>
    </section>
  `;

  bindPatientFinanceActions(root);
}


function renderPatientFinanceKpi({
  icon,
  label,
  value,
  note,
  accent = false,
}) {
  return `
    <article class="patientFinanceKpi ${accent ? "accent" : ""}">
      <div class="patientFinanceKpiIcon">
        ${icon}
      </div>

      <div>
        <span>${escapeHtml(label)}</span>

        <strong>
          ${escapeHtml(value)}
        </strong>

        <small>
          ${escapeHtml(note || "")}
        </small>
      </div>
    </article>
  `;
}


function buildPatientTopServices(visits, limit = 5) {
  const servicesMap = new Map();

  (visits || []).forEach((visit) => {
    const lines = expandServiceLines(visit);

    lines.forEach((line) => {
      const name = String(
        line.name || "Послуга"
      ).trim();

      const key = name.toLowerCase();

      const current =
        servicesMap.get(key) || {
          name,
          quantity: 0,
          total: 0,
          visits: 0,
        };

      current.quantity +=
        Number(line.qty || 0);

      current.total +=
        Number(line.lineTotal || 0);

      current.visits += 1;

      servicesMap.set(key, current);
    });
  });

  return Array.from(servicesMap.values())
    .sort((a, b) => {
      if (b.total !== a.total) {
        return b.total - a.total;
      }

      return b.quantity - a.quantity;
    })
    .slice(0, limit);
}


