function calculatePatientVisitInterval(visits) {
  const uniqueDates = Array.from(
    new Set(
      (visits || [])
        .map((visit) => {
          return String(
            visit.date ||
            visit.created_at ||
            ""
          ).slice(0, 10);
        })
        .filter(Boolean)
    )
  )
    .map((date) => new Date(date))
    .filter((date) => {
      return !Number.isNaN(date.getTime());
    })
    .sort((a, b) => a - b);

  if (uniqueDates.length < 2) return null;

  let totalDays = 0;

  for (
    let index = 1;
    index < uniqueDates.length;
    index += 1
  ) {
    const difference =
      uniqueDates[index] -
      uniqueDates[index - 1];

    totalDays += Math.max(
      0,
      Math.round(
        difference /
        (1000 * 60 * 60 * 24)
      )
    );
  }

  return Math.max(
    1,
    Math.round(
      totalDays /
      (uniqueDates.length - 1)
    )
  );
}


function buildPatientFinanceInsight({
  pet,
  visitsCount,
  totalPaid,
  avgCheck,
  topServices,
  visitInterval,
}) {
  const petName =
    pet?.name || "Пацієнт";

  if (!visitsCount) {
    return `${petName} ще не має завершених візитів із фінансовими даними.`;
  }

  const parts = [];

  parts.push(
    `${petName} відвідав клініку ${visitsCount} ${getPatientVisitCountLabel(visitsCount)}`
  );

  if (visitInterval) {
    parts.push(
      `у середньому раз на ${visitInterval} ${getPatientDayCountLabel(visitInterval)}`
    );
  }

  if (topServices[0]?.name) {
    parts.push(
      `найцінніша послуга — ${topServices[0].name}`
    );
  }

  if (totalPaid > 0) {
    parts.push(
      `загальна сума оплат становить ${formatPatientMoney(totalPaid)}, середній чек — ${formatPatientMoney(avgCheck)}`
    );
  }

  return parts.join(". ") + ".";
}


function formatPatientMoney(value) {
  return (
    Number(value || 0).toLocaleString("uk-UA") +
    " ₴"
  );
}


function formatPatientFinanceDate(value) {
  const raw = String(value || "").slice(0, 10);

  if (!raw) return "—";

  const date = new Date(`${raw}T12:00:00`);

  if (Number.isNaN(date.getTime())) {
    return raw;
  }

  return date.toLocaleDateString("uk-UA", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
  });
}


function getPatientVisitCountLabel(count) {
  const number = Math.abs(Number(count || 0));

  if (number % 10 === 1 && number % 100 !== 11) {
    return "візит";
  }

  if (
    number % 10 >= 2 &&
    number % 10 <= 4 &&
    (
      number % 100 < 12 ||
      number % 100 > 14
    )
  ) {
    return "візити";
  }

  return "візитів";
}


function getPatientServiceCountLabel(count) {
  const number = Math.abs(Number(count || 0));

  if (number % 10 === 1 && number % 100 !== 11) {
    return "раз";
  }

  if (
    number % 10 >= 2 &&
    number % 10 <= 4 &&
    (
      number % 100 < 12 ||
      number % 100 > 14
    )
  ) {
    return "рази";
  }

  return "разів";
}


function getPatientDayCountLabel(count) {
  const number = Math.abs(Number(count || 0));

  if (number % 10 === 1 && number % 100 !== 11) {
    return "день";
  }

  if (
    number % 10 >= 2 &&
    number % 10 <= 4 &&
    (
      number % 100 < 12 ||
      number % 100 > 14
    )
  ) {
    return "дні";
  }

  return "днів";
}
