async function openVisit(visitId, opts = { pushHash: true }) {
  const vid = String(visitId || "").trim();
  if (!vid) return;

  let visit = getVisitByIdSync(vid);

  if (!visit) {
    try {
      const arr = await loadVisitsApi({ id: vid });
      visit = arr?.[0] || null;
    } catch {}
  }

  if (!visit) {
    alert("Візит не знайдено");
    setHash("visits");
    return;
  }

  ensureVisitServicesShape(
  visit
);

ensureVisitStockShape(
  visit
);

try {
  const calendarEvents =
    await loadCalendarApi();

  const linkedCalendarEvent =
    (
      Array.isArray(
        calendarEvents
      )
        ? calendarEvents
        : []
    ).find(
      (event) =>
        String(
          event?.visit_id || ""
        ).trim() ===
        String(
          vid || ""
        ).trim()
    ) || null;

  visit.calendar_event_id =
    linkedCalendarEvent?.id ||
    visit.calendar_event_id ||
    null;

  visit.calendar_status =
    String(
      linkedCalendarEvent?.status ||
      visit.calendar_status ||
      ""
    )
      .trim()
      .toLowerCase();

  cacheVisits([
    visit,
  ]);
} catch (error) {
  console.warn(
    "Не вдалося визначити статус календарного запису:",
    error
  );

  visit.calendar_event_id =
    visit.calendar_event_id ||
    null;

  visit.calendar_status =
    String(
      visit.calendar_status ||
      ""
    )
      .trim()
      .toLowerCase();

  cacheVisits([
    visit,
  ]);
}


state.selectedVisitId =
  vid;

  const patients = Array.isArray(state.patients) && state.patients.length ? state.patients : loadPatients();
  const pet = (patients || []).find((p) => String(p.id) === String(visit.pet_id)) || null;

  if (pet) {
    state.selectedPet = pet;
    state.selectedPetId = String(pet.id);
    state.selectedOwnerId = pet.owner_id || state.selectedOwnerId;
  }

  renderVisitPage(visit, pet);
  if (typeof renderVisitFiles === "function") renderVisitFiles(vid);
  initVisitUI();
  setRoute("visit");

  if (opts.pushHash) setHash("visit", vid);
}

// =========================
// Отрисовка страницы приёма и медицинских блоков
// =========================
async function syncCalendarEventStatusByVisitId(
  visitId,
  nextStatus
) {
  const cleanVisitId =
    String(
      visitId || ""
    ).trim();

  const cleanStatus =
    String(
      nextStatus || ""
    )
      .trim()
      .toLowerCase();

  if (!cleanVisitId) {
    throw new Error(
      "Не вказано ID медичного візиту."
    );
  }

  if (!cleanStatus) {
    throw new Error(
      "Не вказано новий статус календаря."
    );
  }

  const calendarEvents =
    await loadCalendarApi();

  const allEvents =
    Array.isArray(
      calendarEvents
    )
      ? calendarEvents
      : [];

  const cachedVisit =
    getVisitByIdSync(
      cleanVisitId
    );

  const cachedCalendarEventId =
    String(
      cachedVisit
        ?.calendar_event_id ||
      ""
    ).trim();

  let linkedEvents =
    allEvents.filter(
      (event) =>
        String(
          event?.visit_id || ""
        ).trim() ===
        cleanVisitId
    );

  if (
    !linkedEvents.length &&
    cachedCalendarEventId
  ) {
    linkedEvents =
      allEvents.filter(
        (event) =>
          String(
            event?.id || ""
          ).trim() ===
          cachedCalendarEventId
      );
  }

  if (!linkedEvents.length) {
    console.error(
      "Не знайдено календарний запис для візиту:",
      {
        visitId:
          cleanVisitId,

        cachedCalendarEventId,

        calendarEvents:
          allEvents,
      }
    );

    throw new Error(
      (
        "Медичні дані збережено, " +
        "але календарний запис, " +
        "пов’язаний із візитом, " +
        "не знайдено."
      )
    );
  }

  const updatedEvents =
    [];

  for (
    const linkedEvent
    of linkedEvents
  ) {
    const updated =
      await updateCalendarEventApi(
        linkedEvent.id,
        {
          title:
            linkedEvent.title ||
            "Прийом",

          event_date:
            linkedEvent.event_date,

          start_time:
            linkedEvent.start_time,

          end_time:
            linkedEvent.end_time,

          staff_id:
            linkedEvent.staff_id,

          patient_id:
            linkedEvent.patient_id ||
            null,

          owner_id:
            linkedEvent.owner_id ||
            null,

          visit_id:
            cleanVisitId,

          location:
            linkedEvent.location ||
            "",

          note:
            linkedEvent.note ||
            "",

          status:
            cleanStatus,
        }
      );

    if (!updated?.id) {
      throw new Error(
        (
          "Сервер не підтвердив " +
          "оновлення календарного запису."
        )
      );
    }

    const returnedStatus =
      String(
        updated.status || ""
      )
        .trim()
        .toLowerCase();

    if (
      returnedStatus !==
      cleanStatus
    ) {
      console.error(
        "Calendar status was not saved:",
        {
          expected:
            cleanStatus,

          returned:
            returnedStatus,

          event:
            updated,
        }
      );

      throw new Error(
        (
          "Сервер повернув календарний запис, " +
          "але не зберіг статус «Завершено»."
        )
      );
    }

    updatedEvents.push(
      updated
    );
  }

  const primaryEvent =
    updatedEvents.find(
      (event) =>
        String(
          event.id || ""
        ) ===
        cachedCalendarEventId
    ) ||
    updatedEvents[0];

  const mergedVisit = {
    ...(cachedVisit || {}),

    calendar_event_id:
      primaryEvent?.id ||
      cachedCalendarEventId ||
      null,

    calendar_status:
      cleanStatus,
  };

  cacheVisits([
    mergedVisit,
  ]);

  console.log(
    "Календарні записи синхронізовано:",
    {
      visitId:
        cleanVisitId,

      status:
        cleanStatus,

      updatedEventIds:
        updatedEvents.map(
          (event) =>
            event.id
        ),
    }
  );

  return primaryEvent;
}
