function initVisitNewPatientBreedPicker() {
  const speciesSelect =
    document.querySelector(
      "#visitNewPetSpecies"
    );

  const breedInput =
    document.querySelector(
      "#visitNewPetBreed"
    );

  const breedList =
    document.querySelector(
      "#visitNewPetBreedList"
    );

  const breedLabel =
    document.querySelector(
      "#visitNewPetBreedLabel"
    );

  if (
    !speciesSelect ||
    !breedInput ||
    !breedList
  ) {
    return;
  }

  const renderBreedOptions = () => {
    const species =
      String(
        speciesSelect.value || ""
      ).trim();

    let breeds = [];

    breedInput.value = "";
    breedList.innerHTML = "";

    if (species === "dog") {
      breeds = DOG_BREEDS;

      breedInput.disabled = false;

      breedInput.placeholder =
        "Почніть вводити породу собаки";

      if (breedLabel) {
        breedLabel.textContent =
          "Порода собаки";
      }
    } else if (species === "cat") {
      breeds = CAT_BREEDS;

      breedInput.disabled = false;

      breedInput.placeholder =
        "Почніть вводити породу кота";

      if (breedLabel) {
        breedLabel.textContent =
          "Порода кота";
      }
    } else if (species === "other") {
  breeds =
    OTHER_SPECIES_LIST;

  breedInput.disabled =
    false;

  breedInput.placeholder =
    "Оберіть або почніть вводити вид тварини";

  if (breedLabel) {
    breedLabel.textContent =
      "Вид тварини";
  }
} else {
      breedInput.disabled = true;

      breedInput.placeholder =
        "Спочатку оберіть вид";

      if (breedLabel) {
        breedLabel.textContent =
          "Порода";
      }
    }

    breedList.innerHTML =
      breeds
        .map(
          (breed) => `
            <option
              value="${escapeHtml(breed)}"
            ></option>
          `
        )
        .join("");
  };

  speciesSelect.addEventListener(
    "change",
    renderBreedOptions
  );

  renderBreedOptions();
}

initVisitNewPatientBreedPicker();

