const normalizeBreedSearch = (value) => {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replaceAll("ё", "е")
    .replaceAll("’", "'")
    .replaceAll("`", "'");
};

const closeBreedDropdown = () => {
  breedDropdown.classList.remove("is-open");
  breedDropdown.innerHTML = "";
};

const renderBreedDropdown =
  () => {
    const query =
      normalizeBreedSearch(
        breedInput.value
      );

    const isOtherSpecies =
      speciesInput.value ===
      "other";

    if (
      isOtherSpecies &&
      !query &&
      !activeOtherGroupId
    ) {
      breedDropdown.innerHTML =
        `
          <div
            class="addPetBreedEmpty"
          >
            <span>
              Оберіть категорію
            </span>

            <small>
              Після цього відкриється
              список конкретних видів.
            </small>
          </div>

          ${OTHER_SPECIES_GROUPS
            .map(
              (group) => `
                <button
                  class="addPetBreedOption"
                  type="button"
                  data-other-species-group="${
                    escapeHtml(
                      group.id
                    )
                  }"
                >
                  <span
                    class="addPetBreedOptionIcon"
                  >
                    ${
                      escapeHtml(
                        group.icon
                      )
                    }
                  </span>

                  <span>
                    ${
                      escapeHtml(
                        group.title
                      )
                    }
                  </span>

                  <b>›</b>
                </button>
              `
            )
            .join("")}
        `;

      breedDropdown.classList.add(
        "is-open"
      );

      return;
    }

    const activeGroup =
      isOtherSpecies &&
      activeOtherGroupId
        ? OTHER_SPECIES_GROUPS
            .find(
              (group) =>
                group.id ===
                activeOtherGroupId
            )
        : null;

    const sourceList =
      activeGroup
        ? activeGroup.items
        : activeBreedList;

    const filtered =
      sourceList
        .filter((item) => {
          if (!query) {
            return true;
          }

          return normalizeBreedSearch(
            item
          ).includes(query);
        })
        .slice(0, 20);

    const backButton =
      activeGroup &&
      !query
        ? `
            <button
              class="addPetBreedOption"
              type="button"
              data-other-species-back="1"
            >
              <span
                class="addPetBreedOptionIcon"
              >
                ←
              </span>

              <span>
                Усі категорії
              </span>
            </button>

            <div
              class="addPetBreedEmpty"
            >
              <span>
                ${
                  escapeHtml(
                    activeGroup.icon
                  )
                }
                ${
                  escapeHtml(
                    activeGroup.title
                  )
                }
              </span>

              <small>
                Оберіть конкретний вид
                тварини.
              </small>
            </div>
          `
        : "";

    breedDropdown.innerHTML =
      filtered.length
        ? `
            ${backButton}

            ${filtered
              .map(
                (item) => `
                  <button
                    class="addPetBreedOption ${
                      selectedBreed ===
                      item
                        ? "is-selected"
                        : ""
                    }"
                    type="button"
                    data-select-breed="${
                      escapeHtml(
                        item
                      )
                    }"
                  >
                    <span
                      class="addPetBreedOptionIcon"
                    >
                      ${
                        activeGroup
                          ? escapeHtml(
                              activeGroup
                                .icon
                            )
                          : "🐾"
                      }
                    </span>

                    <span>
                      ${
                        escapeHtml(
                          item
                        )
                      }
                    </span>

                    ${
                      selectedBreed ===
                      item
                        ? "<b>✓</b>"
                        : ""
                    }
                  </button>
                `
              )
              .join("")}
          `
        : `
            ${backButton}

            <div
              class="addPetBreedEmpty"
            >
              <span>
                Нічого не знайдено
              </span>

              <small>
                Ви можете залишити
                введений варіант
                вручну.
              </small>
            </div>
          `;

    breedDropdown.classList.add(
      "is-open"
    );
  };

