function initOwnerUI() {
  // Добавление животного владельцу
  $("#btnAddPet")?.addEventListener("click", () => {
    const ownerId = state.selectedOwnerId;

    if (!ownerId) {
      alert("Спочатку обери власника");
      return;
    }

    openAddPetModal(ownerId);
  });

  // Клик по списку животных (Удаление / Открытие)
  $("#petsList")?.addEventListener(
  "click",
  async (e) => {
    const editBtn =
      e.target.closest(
        "[data-edit-owner-pet]"
      );

    if (editBtn) {
      e.preventDefault();
      e.stopPropagation();

      const petId =
        editBtn.dataset
          .editOwnerPet;

      if (!petId) {
        return;
      }

      const pet =
        (
          state.patients || []
        ).find(
          (item) =>
            String(item.id) ===
            String(petId)
        );

      if (!pet) {
        openDeleteModal(
          "Пацієнта не знайдено.",
          null,
          "info"
        );

        return;
      }

      openAddPetModal(
        pet.owner_id,
        pet
      );

      return;
    }

    const delBtn =
      e.target.closest(
        "[data-del-pet]"
      );

    if (delBtn) {
      e.preventDefault();
      e.stopPropagation();

      const petId =
        delBtn.dataset
          .delPet;

      if (!petId) {
        return;
      }

      const pet =
        (
          state.patients || []
        ).find(
          (item) =>
            String(item.id) ===
            String(petId)
        );

      const petName =
        pet?.name ||
        "цього пацієнта";

      openDeleteModal(
        `
          <b>
            ${escapeHtml(petName)}
          </b>
          <br><br>
          Цю дію неможливо скасувати.
        `,
        async () => {
          const ok =
            await deletePatientApi(
              petId
            );

          if (!ok) {
            openDeleteModal(
              "Не вдалося видалити пацієнта.",
              null,
              "info"
            );

            return;
          }

          await loadPatientsApi();

          if (
            String(
              state.selectedPetId ||
              ""
            ) ===
            String(petId)
          ) {
            state.selectedPetId =
              null;

            state.selectedPet =
              null;
          }

          if (
            state.selectedOwnerId
          ) {
            await renderOwnerPage(
              state.selectedOwnerId
            );
          }
        }
      );

      return;
    }

    const openZone =
      e.target.closest(
        "[data-open-pet]"
      );

    if (openZone) {
      const petId =
        openZone.dataset
          .openPet;

      if (petId) {
        openPatient(
          petId
        );
      }
    }
  }
);
}
