// =========================
// Спецификации видов животных и нормализаторы
// =========================
function normalizeSpecies(value) {
  const s = String(value || "")
    .toLowerCase()
    .trim();

  if (
    s === "dog" ||
    s.includes("пес") ||
    s.includes("соб") ||
    s.includes("dog")
  ) {
    return "dog";
  }

  if (
    s === "cat" ||
    s.includes("кот") ||
    s.includes("кіт") ||
    s.includes("cat")
  ) {
    return "cat";
  }

  return "dog";
}

function speciesLabel(value) {
  const key = normalizeSpecies(value);

  if (key === "cat") {
    return "кіт";
  }

  return "пес";
}

function askSpecies(current = "dog") {
  const cur = normalizeSpecies(current);

  const raw = prompt(
    "Вид пацієнта:\n1 — пес\n2 — кіт",
    cur === "cat" ? "2" : "1"
  );

  if (raw === null) {
    return null;
  }

  const value = String(raw)
    .trim()
    .toLowerCase();

  if (
    value === "2" ||
    value === "cat" ||
    value.includes("кот") ||
    value.includes("кіт")
  ) {
    return "cat";
  }

  return "dog";
}


