async function updatePatientApi(petId, payload = {}) {
  try {
    const bodyObj = {
  name:
    String(
      payload.name || ""
    ).trim(),

  species:
    String(
      payload.species || ""
    ).trim(),

  breed:
    String(
      payload.breed || ""
    ).trim(),

  age:
    String(
      payload.age || ""
    ).trim(),

  weight_kg:
    String(
      payload.weight_kg || ""
    ).trim(),

  sex:
    String(
      payload.sex || ""
    ).trim(),

  neutered:
    typeof payload.neutered ===
      "boolean"
      ? payload.neutered
      : null,

  vaccination_status:
  String(
    payload.vaccination_status ||
    "unknown"
  ).trim(),

vaccination_date:
  String(
    payload.vaccination_date ||
    ""
  ).trim(),

vaccination_name:
  String(
    payload.vaccination_name ||
    ""
  ).trim(),

notes:
    String(
      payload.notes || ""
    ).trim(),
};

    Object.keys(
  bodyObj
).forEach((key) => {
  if (
    bodyObj[key] === "" ||
    bodyObj[key] === null
  ) {
    delete bodyObj[key];
  }
});

    const res = await fetch(`/api/patients/${encodeURIComponent(petId)}`, {
      method: "PUT",
      credentials: "include",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify(bodyObj),
    });

    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok) {
      console.error("API /patients PUT HTTP", res.status, text);
      alert(`Помилка оновлення пацієнта (HTTP ${res.status})`);
      return null;
    }

    if (!json || !json.ok) {
      console.error("API /patients PUT bad json:", json, text);
      alert(json?.error || "Помилка оновлення пацієнта");
      return null;
    }

    return Array.isArray(json.data) ? (json.data[0] || null) : (json.data || null);
  } catch (e) {
    console.error("updatePatientApi failed:", e);
    alert("Помилка зʼєднання з сервером");
    return null;
  }
}
async function savePatientNotesApi(
  patientId,
  notes
) {
  const response =
    await fetch(
      `/api/patients/${
        encodeURIComponent(
          String(patientId)
        )
      }`,
      {
        method: "PUT",

        credentials:
          "include",

        headers: {
          "Content-Type":
            "application/json",

          Accept:
            "application/json",

          ...getOrgHeaders(),
        },

        body:
          JSON.stringify({
            notes:
              String(
                notes || ""
              ).trim(),
          }),
      }
    );


  const text =
    await response.text();


  let json = null;

  try {
    json =
      text
        ? JSON.parse(
            text
          )
        : null;
  } catch {
    json = null;
  }


  if (
    !response.ok ||
    !json ||
    json.ok !== true
  ) {
    throw new Error(
      json?.error ||
      "Не вдалося зберегти нотатки."
    );
  }


  return Array.isArray(
    json.data
  )
    ? json.data[0] || null
    : json.data || null;
}
