// DELETE — server-first (patients + visits)
// =========================
async function deletePatientApi(petId) {
  try {
    const res = await fetch(`/api/patients/${encodeURIComponent(petId)}`, {
      method: "DELETE",
      credentials: "include",
      headers: { Accept: "application/json", ...getOrgHeaders() },
    });

    const text = await res.text();
    let json = null;
    try { json = text ? JSON.parse(text) : null; } catch {}

    if (!res.ok) {
      console.error("API /patients DELETE HTTP", res.status, text);
      alert(`Помилка сервера при видаленні пацієнта (HTTP ${res.status})`);
      return false;
    }

    if (!json || !json.ok) {
      console.error("API /patients DELETE bad json:", text);
      alert(json?.error || "Помилка видалення пацієнта");
      return false;
    }
    return true;
  } catch (e) {
    console.error("deletePatientApi failed:", e);
    alert("Помилка зʼєднання з сервером");
    return false;
  }
}

async function deletePatientEverywhere(petId) {
  const id = String(petId || "");
  if (!id) return;

  const patients =
    Array.isArray(state.patients) && state.patients.length
      ? state.patients
      : loadPatients();

  const pet = patients.find(
    (item) => String(item.id) === id
  );

  if (!pet) {
    alert("Пацієнта не знайдено.");
    return;
  }

  const petName = pet.name || "Без імені";

  openDeleteModal(
    `
      <b>${escapeHtml(petName)}</b>
      <br><br>
      Пацієнта буде видалено назавжди разом із його карткою.
      <br>
      Цю дію неможливо скасувати.
    `,
    async () => {
      const ok = await deletePatientApi(id);

      if (!ok) {
        alert("Не вдалося видалити пацієнта.");
        return;
      }

      await loadPatientsApi();

      if (String(state.selectedPetId || "") === id) {
        state.selectedPetId = null;
        state.selectedPet = null;
        state.selectedVisitId = null;
      }

      if (state.route === "patients") {
        renderPatientsTab();
      }

      if (state.selectedOwnerId) {
        renderOwnerPage(state.selectedOwnerId);
      }

      if (state.route === "visits") {
        renderVisitsTab();
      }
    }
  );
}

async function deleteVisitEverywhere(visitId) {
  if (!visitId) return false;
  if (!confirm("Видалити візит назавжди?")) return false;

  const ok = await deleteVisitApi(visitId);
  if (!ok) return false;

  if (state.selectedVisitId === visitId) {
    state.selectedVisitId = null;
    if (state.selectedPetId) openPatient(state.selectedPetId);
    else setHash("visits");
  }

  if (state.route === "visits") renderVisitsTab();
  if (state.selectedPetId) await renderVisits(state.selectedPetId);
  return true;
}

function loadStock() {
  return Array.isArray(state.stock)
    ? state.stock
    : [];
}


function saveStock(items) {
  state.stock = Array.isArray(items)
    ? items.map(normalizeStockItem)
    : [];

  state.stockLoaded = true;

  return state.stock;
}


function getStockById(id) {
  const stockId =
    String(id || "");

  return (
    loadStock().find(
      (item) =>
        String(item.id) === stockId
    ) || null
  );
}


async function stockApiRequest(
  url,
  options = {}
) {
  const response =
    await fetch(
      url,
      {
        credentials: "include",

        ...options,

        headers: {
          Accept:
            "application/json",

          ...(options.body
            ? {
                "Content-Type":
                  "application/json",
              }
            : {}),

          ...(options.headers || {}),
        },
      }
    );

  const text =
    await response.text();

  let json = null;

  try {
    json = text
      ? JSON.parse(text)
      : null;
  } catch {}

  if (
    !response.ok ||
    json?.ok !== true
  ) {
    throw new Error(
      json?.error ||
      `HTTP ${response.status}`
    );
  }

  return json.data;
}


async function loadStockApi(
  force = false
) {
  if (
    state.stockLoaded &&
    !force
  ) {
    return loadStock();
  }

  try {
    const data =
      await stockApiRequest(
        "/api/stock",
        {
          method: "GET",
        }
      );

    state.stock =
      Array.isArray(data)
        ? data.map(
            normalizeStockItem
          )
        : [];

    state.stockLoaded = true;

    return state.stock;

  } catch (error) {
    console.error(
      "loadStockApi failed:",
      error
    );

    state.stock = [];
    state.stockLoaded = false;

    return [];
  }
}

async function createStockItemApi(
  payload
) {
  const data =
    await stockApiRequest(
      "/api/stock",
      {
        method: "POST",
        body: JSON.stringify(
          payload || {}
        ),
      }
    );

  const item =
    normalizeStockItem(data);

  state.stock = [
    item,
    ...loadStock(),
  ];

  state.stockLoaded = true;

  return item;
}


async function updateStockItemApi(
  stockId,
  payload
) {
  const previousItem =
    getStockById(stockId);

  const data =
    await stockApiRequest(
      `/api/stock/${encodeURIComponent(
        stockId
      )}`,
      {
        method: "PUT",
        body: JSON.stringify(
          payload || {}
        ),
      }
    );

  const updatedItem =
    normalizeStockItem({
      ...previousItem,
      ...data,
    });

  state.stock =
    loadStock().map((item) =>
      String(item.id) ===
      String(stockId)
        ? updatedItem
        : item
    );

  state.stockLoaded = true;

  return updatedItem;
}
async function adjustStockItemApi(
  stockId,
  {
    mode,
    quantity,
    comment = "",
  }
) {
  const previousItem =
    getStockById(stockId);

  const movementType =
    mode === "income"
      ? "income"
      : "writeoff";

  const data =
    await stockApiRequest(
      `/api/stock/${encodeURIComponent(
        stockId
      )}/adjust`,
      {
        method: "POST",

        body: JSON.stringify({
          movement_type:
            movementType,

          type:
            movementType,

          mode:
            movementType,

          quantity:
            Number(quantity),

          comment:
            String(comment || ""),
        }),
      }
    );

  const movementQuantity =
    Math.max(
      0,
      Number(quantity) || 0
    );

  const usage30d =
    Math.max(
      0,
      Number(
        previousItem?.usage_30d
      ) || 0
    ) +
    (
      movementType === "writeoff"
        ? movementQuantity
        : 0
    );

  const avgDailyUsage =
    usage30d / 30;

  const updatedQty =
    Math.max(
      0,
      Number(data?.qty) || 0
    );

  const updatedItem =
    normalizeStockItem({
      ...previousItem,
      ...data,
      usage_30d: usage30d,
      avg_daily_usage:
        avgDailyUsage,
      estimated_days_left:
        avgDailyUsage > 0
          ? updatedQty /
            avgDailyUsage
          : null,
    });

  state.stock =
    loadStock().map((item) =>
      String(item.id) ===
      String(stockId)
        ? updatedItem
        : item
    );

  state.stockLoaded = true;

  return updatedItem;
}
async function deleteStockItemApi(
  stockId
) {
  await stockApiRequest(
    `/api/stock/${encodeURIComponent(
      stockId
    )}`,
    {
      method: "DELETE",
    }
  );

  state.stock =
    loadStock().filter(
      (item) =>
        String(item.id) !==
        String(stockId)
    );

  state.stockLoaded = true;

  return true;
}

