function bindPersonalSettingsUI(page) {
  const savedTheme = LS.get(
    "docpug_clinic_theme",
    "purple"
  );
  let selectedTheme =
    document.body.dataset.theme ||
    savedTheme;

  page
    .querySelectorAll("[data-theme-set]")
    .forEach((button) => {
      const theme = button.dataset.themeSet;

      button.classList.toggle(
        "active",
        theme === selectedTheme
      );

      button.addEventListener("click", () => {
        selectedTheme = theme;
        document.body.dataset.theme = theme;
        LS.set(
          "docpug_clinic_theme",
          theme
        );

        page
          .querySelectorAll("[data-theme-set]")
          .forEach((item) => {
            item.classList.remove("active");
          });

        button.classList.add("active");
      });
    });

  const saveThemeButton =
    page.querySelector("#saveClinicThemeButton");
  const saveThemeStatus =
    page.querySelector("#clinicThemeSaveStatus");

  saveThemeButton?.addEventListener(
    "click",
    async () => {
      saveThemeButton.disabled = true;
      saveThemeButton.textContent = "Зберігаємо…";

      if (saveThemeStatus) {
        saveThemeStatus.textContent = "";
        saveThemeStatus.classList.remove("error");
      }

      try {
        const response = await fetch(
          "/api/organization/theme",
          {
            method: "PUT",
            credentials: "include",
            headers: {
              "Content-Type": "application/json",
              Accept: "application/json",
            },
            body: JSON.stringify({
              theme: selectedTheme,
            }),
          }
        );
        const payload = await response.json();

        if (!response.ok || !payload?.ok) {
          throw new Error(
            payload?.error ||
            "Не вдалося зберегти тему"
          );
        }

        const persistedTheme =
          payload.data?.theme ||
          selectedTheme;

        document.body.dataset.theme =
          persistedTheme;
        LS.set(
          "docpug_clinic_theme",
          persistedTheme
        );

        if (saveThemeStatus) {
          saveThemeStatus.textContent =
            "Тему збережено для клініки";
        }
      } catch (error) {
        if (saveThemeStatus) {
          saveThemeStatus.textContent =
            error.message ||
            "Не вдалося зберегти тему";
          saveThemeStatus.classList.add("error");
        }
      } finally {
        saveThemeButton.disabled = false;
        saveThemeButton.textContent =
          "Зберегти тему";
      }
    }
  );



  const languageSelect =
    page.querySelector("#systemLanguageSelect");

    if (languageSelect) {
    languageSelect.value = LS.get(
      "docpug_clinic_lang",
      "uk"
    );

    languageSelect.addEventListener(
      "change",
      () => {
        LS.set(
          "docpug_clinic_lang",
          languageSelect.value
        );
      }
    );
  }
}


function bindSettingsLogoutUI(page) {
  const oldLogoutButton =
    document.getElementById(
      "btn-logout"
    ) ||
    page.querySelector(
      "#btnClinicLogout"
    );

  if (!oldLogoutButton) {
    return;
  }

  const logoutButton =
    oldLogoutButton.cloneNode(true);

  oldLogoutButton.replaceWith(
    logoutButton
  );

  logoutButton.addEventListener(
    "click",
    (event) => {
      event.preventDefault();
      event.stopPropagation();

      openDeleteModal(
        `
          Ви завершите поточну сесію
          та повернетеся на сторінку входу.
        `,
        async () => {
          const originalText =
            logoutButton.textContent;

          logoutButton.disabled =
            true;

          logoutButton.textContent =
            "Вихід…";

          try {
            const response =
              await fetch(
                "/api/logout",
                {
                  method: "POST",
                  credentials:
                    "include",
                  cache: "no-store",

                  headers: {
                    Accept:
                      "application/json",
                  },
                }
              );

            const text =
              await response.text();

            let json = null;

            try {
              json = text
                ? JSON.parse(text)
                : null;
            } catch {
              json = null;
            }

            if (
              !response.ok ||
              json?.ok !== true
            ) {
              throw new Error(
                json?.error ||
                `Logout HTTP ${response.status}`
              );
            }

            state.me = null;
            state.clinicProfile =
              null;

            [
              "pug_active_org_id",
              "pug_active_username",
              "pug_active_display_name",
              "pug_active_role",
              "pug_active_clinic_name",
            ].forEach((key) => {
              sessionStorage.removeItem(
                key
              );
            });

            window.location.replace(
              "/?logged_out=1"
            );

          } catch (error) {
            console.error(
              "Logout failed:",
              error
            );

            openDeleteModal(
              `
                Не вдалося завершити сесію.
                Спробуйте ще раз.
              `,
              null,
              "info"
            );

            logoutButton.disabled =
              false;

            logoutButton.textContent =
              originalText;
          }
        },
        "logout"
      );
    }
  );
}


